// Curated, distinct characters. A form or costume is not another character.
// Compact bilingual editorial records are expanded by manga-data.js.
const mangaRoster = (() => {
  const entry = (name, wiki, group, fr, en, skillFr, skillEn, fights, familyFr = '', familyEn = '') => ({ name, wiki, group, summary: { fr, en }, skill: { fr: skillFr, en: skillEn }, fights: fights.split('|').filter(Boolean), family: { fr: familyFr, en: familyEn } });
  const onepiece = [
    entry('Nico Robin', 'robin', 'Chapeau de paille', 'Rescapée du massacre d’Ohara, Robin apprend à lire les Ponéglyphes auprès des archéologues. Après Baroque Works, elle rejoint Luffy. À Enies Lobby, ses compagnons lui donnent le courage de vouloir vivre ; elle poursuit depuis la vérité du Siècle oublié.', 'A survivor of Ohara, Robin learns to read Poneglyphs from its archaeologists. After Baroque Works she joins Luffy. At Enies Lobby her friends give her the courage to want to live; she continues seeking the truth of the Void Century.', 'Hana Hana no Mi — membres et Demonio Fleur', 'Flower-Flower Fruit — limbs and Demonio Fleur', 'Robin vs Yama@Skypiea|Robin vs Hammond@Fishman|Robin vs Black Maria@Wano', 'Fille de Nico Olvia ; les archéologues d’Ohara l’ont élevée.', 'Daughter of Nico Olvia; raised by Ohara’s archaeologists.'),
    entry('Franky', 'franky', 'Chapeau de paille', 'Né Cutty Flam, Franky est recueilli par le charpentier Tom. Après l’accident du train marin, il reconstruit son corps en cyborg. Il aide à sauver Robin, construit le Thousand Sunny et part voir son navire traverser Grand Line avec Luffy.', 'Born Cutty Flam, Franky is taken in by shipwright Tom. After the sea-train accident he rebuilds himself as a cyborg. He helps rescue Robin, builds the Thousand Sunny and sails with Luffy to see his ship cross Grand Line.', 'Cyborg — Radical Beam et General Franky', 'Cyborg — Radical Beam and General Franky', 'Franky vs Fukuro@Enies|Franky vs Senor Pink@Dressrosa|Franky vs Sasaki@Wano', 'Tom est son père de cœur ; Iceburg est son compagnon d’apprentissage.', 'Tom is his father figure; Iceburg is his fellow apprentice.'),
    entry('Brook', 'brook', 'Chapeau de paille', 'Musicien des Rumbar Pirates, Brook promet de retrouver Laboon. Son fruit le ramène à la vie, mais il retrouve son corps sous forme de squelette. Libéré de l’emprise de Moria avec l’aide des Mugiwara, il devient leur musicien et apprend à employer son âme au combat.', 'A Rumbar Pirates musician, Brook promises to return to Laboon. His fruit revives him, but he finds his body as a skeleton. Freed from Moria’s shadow theft with the Straw Hats’ help, he becomes their musician and learns to use his soul in battle.', 'Yomi Yomi no Mi — âme et escrime glacée', 'Revive-Revive Fruit — soul and freezing swordsmanship', 'Brook vs Ryuma@Thriller|Brook vs Zeo@Fishman|Brook vs Big Mom@WholeCake', 'Les Rumbar Pirates étaient son équipage ; Laboon attend leur retour.', 'The Rumbar Pirates were his crew; Laboon awaits their return.'),
    entry('Jinbe', 'Jinbe', 'Chapeau de paille', 'Homme-poisson et ancien capitaine des Pirates du Soleil, Jinbe devient Grand Corsaire pour défendre les siens. Il refuse de combattre Barbe Blanche, aide Luffy à Impel Down et Marineford puis quitte l’alliance de Big Mom. Il rejoint le Sunny comme timonier.', 'A fish-man and former Sun Pirates captain, Jinbe becomes a Warlord to protect his people. He refuses to fight Whitebeard, helps Luffy at Impel Down and Marineford, then leaves Big Mom’s alliance. He joins the Sunny as helmsman.', 'Karaté des hommes-poissons', 'Fish-Man Karate', 'Jinbe vs Ace@Past|Jinbe vs Moria@Marineford|Jinbe vs Who’s-Who@Wano', 'Fisher Tiger est son ancien capitaine ; les Pirates du Soleil sont ses compagnons.', 'Fisher Tiger is his former captain; the Sun Pirates are his companions.'),
    entry('Portgas D. Ace', 'ace', 'Barbe Blanche', 'Fils de Roger, Ace grandit avec Luffy et Sabo sous la garde de Dadan. Il fonde les Spade Pirates puis trouve une famille chez Barbe Blanche. Sa poursuite de Teach le mène à la capture ; à Marineford, il protège Luffy d’Akainu au prix de sa vie.', 'Roger’s son, Ace grows up with Luffy and Sabo under Dadan’s care. He founds the Spade Pirates, then finds a family with Whitebeard. Pursuing Teach leads to his capture; at Marineford he gives his life protecting Luffy from Akainu.', 'Mera Mera no Mi — feu', 'Flame-Flame Fruit — fire', 'Ace vs Jinbe@Past|Ace vs Blackbeard@Banaro|Ace vs Akainu@Marineford', 'Fils de Roger et Rouge ; frère de cœur de Luffy et Sabo.', 'Son of Roger and Rouge; sworn brother of Luffy and Sabo.'),
    entry('Sabo', 'sabo', 'Révolutionnaires', 'Sabo abandonne sa famille noble pour vivre libre avec Ace et Luffy. Dragon le sauve après l’attaque d’un Dragon céleste. Devenu révolutionnaire, il retrouve ses souvenirs après la mort d’Ace et hérite de son fruit à Dressrosa, où il retrouve Luffy.', 'Sabo leaves his noble family to live freely with Ace and Luffy. Dragon saves him after a Celestial Dragon’s attack. As a revolutionary he regains his memories after Ace’s death and inherits Ace’s fruit at Dressrosa, reuniting with Luffy.', 'Ryusoken et Mera Mera no Mi', 'Dragon Claw Fist and Flame-Flame Fruit', 'Sabo vs Burgess@Dressrosa|Sabo vs Fujitora@Dressrosa|Sabo vs Bastille@Dressrosa', 'Fils d’Outlook III et Didit ; frère de cœur d’Ace et Luffy.', 'Son of Outlook III and Didit; sworn brother of Ace and Luffy.'),
    entry('Shanks', 'Shanks', 'Roux', 'Ancien apprenti sur le navire de Roger, Shanks fonde son propre équipage. Il sauve Luffy d’un monstre marin et lui confie son chapeau. Devenu Empereur, il met fin à la guerre de Marineford et défend ses alliés du Nouveau Monde.', 'A former apprentice aboard Roger’s ship, Shanks founds his own crew. He saves Luffy from a Sea King and entrusts him with his hat. As an Emperor he ends the Marineford war and protects his New World allies.', 'Haki des Rois et Kamusari', 'Conqueror’s Haki and Divine Departure', 'Shanks vs Whitebeard@NewWorld|Shanks vs Akainu@Marineford|Shanks vs Kid@Elbaf', 'Roger est son ancien capitaine ; Buggy était son camarade d’apprentissage.', 'Roger is his former captain; Buggy was his fellow apprentice.'),
    entry('Edward Newgate', 'Newgate', 'Barbe Blanche', 'Surnommé Barbe Blanche, Newgate rêve avant tout d’une famille. Ancien membre de Rocks, il bâtit un équipage dont il considère les membres comme ses fils. À Marineford, il tente de sauver Ace et meurt debout après avoir confirmé l’existence du One Piece.', 'Known as Whitebeard, Newgate dreams above all of a family. A former Rocks pirate, he builds a crew whose members he considers his sons. At Marineford he tries to save Ace and dies standing after confirming that the One Piece exists.', 'Gura Gura no Mi — séismes', 'Tremor-Tremor Fruit — earthquakes', 'Whitebeard vs Roger@Past|Whitebeard vs Akainu@Marineford|Whitebeard vs Blackbeard@Marineford', 'Son équipage forme sa famille choisie ; Ace est l’un de ses commandants.', 'His crew is his chosen family; Ace is one of his commanders.'),
    entry('Marshall D. Teach', 'Teach', 'Barbe Noire', 'Teach quitte l’équipage de Barbe Blanche après avoir tué Thatch pour obtenir le fruit des ténèbres. Il capture Ace, profite d’Impel Down pour recruter des prisonniers puis vole le pouvoir de Newgate à Marineford. Il devient Empereur avec deux pouvoirs de fruits.', 'Teach leaves Whitebeard’s crew after killing Thatch to obtain the darkness fruit. He captures Ace, recruits prisoners from Impel Down and steals Newgate’s power at Marineford. He becomes an Emperor possessing two Devil Fruit powers.', 'Yami Yami no Mi et Gura Gura no Mi', 'Dark-Dark Fruit and Tremor-Tremor Fruit', 'Blackbeard vs Ace@Banaro|Blackbeard vs Whitebeard@Marineford|Blackbeard vs Law@Winner'),
    entry('Charlotte Linlin', 'big_mom', 'Big Mom', 'Big Mom dirige Totto Land avec ses enfants et aspire à réunir toutes les races autour de sa table. Ancienne pirate de Rocks, elle domine grâce aux âmes et aux Homies. Les événements de Whole Cake Island la conduisent à Wano, où Law et Kid la renversent.', 'Big Mom rules Totto Land with her children and wishes to gather all races at her table. A former Rocks pirate, she dominates through souls and Homies. The Whole Cake Island events bring her to Wano, where Law and Kid defeat her.', 'Soru Soru no Mi — âmes et Homies', 'Soul-Soul Fruit — souls and Homies', 'Big Mom vs Brook@WholeCake|Big Mom vs Queen@Wano|Big Mom vs Law and Kid@Wano', 'Mère de la famille Charlotte ; Katakuri et Perospero sont ses fils.', 'Mother of the Charlotte family; Katakuri and Perospero are her sons.'),
    entry('Kaido', 'kaidou', 'Cent Bêtes', 'Ancien pirate de Rocks, Kaido conquiert Wano avec Orochi et transforme le pays en arsenal. Son équipage des Cent Bêtes utilise de nombreux Zoans. L’alliance de Luffy et des samouraïs l’affronte sur Onigashima ; le réveil de Luffy met fin à sa domination.', 'A former Rocks pirate, Kaido conquers Wano with Orochi and turns it into an arsenal. His Beast Pirates use many Zoans. Luffy’s alliance with the samurai fights him on Onigashima; Luffy’s awakening ends his rule.', 'Zoan mythique du dragon azur', 'Mythical Azure Dragon Zoan', 'Kaido vs Oden@Wano|Kaido vs Yamato@Wano|Kaido vs Luffy@Wano', 'Père de Yamato.', 'Yamato’s father.'),
    entry('Baggy', 'buggy', 'Cross Guild', 'Ancien apprenti de Roger aux côtés de Shanks, Baggy utilise son corps fragmenté pour échapper aux attaques tranchantes. Ses aventures d’East Blue, d’Impel Down et de Marineford construisent sa réputation. Cross Guild lui donne ensuite le titre d’Empereur malgré sa peur de Mihawk et Crocodile.', 'A former Roger apprentice alongside Shanks, Buggy splits his body to evade cutting attacks. His East Blue, Impel Down and Marineford adventures build his reputation. Cross Guild later makes him an Emperor despite his fear of Mihawk and Crocodile.', 'Bara Bara no Mi — fragmentation', 'Chop-Chop Fruit — separation', 'Buggy vs Luffy@EastBlue|Buggy vs Zoro@EastBlue|Buggy vs Mihawk@Marineford'),
    entry('Dracule Mihawk', 'mihawk', 'Cross Guild', 'Le meilleur épéiste du monde voyage d’abord seul et mesure les ambitions de Zoro au Baratie. Ancien rival de Shanks et Grand Corsaire, il entraîne Zoro pendant l’ellipse. Après la dissolution des Corsaires, il rejoint Crocodile dans Cross Guild.', 'The world’s strongest swordsman initially travels alone and tests Zoro’s ambition at the Baratie. A former Shanks rival and Warlord, he trains Zoro during the time skip. After the Warlords are dissolved he joins Crocodile in Cross Guild.', 'Yoru — escrime et Haki', 'Yoru — swordsmanship and Haki', 'Mihawk vs Zoro@EastBlue|Mihawk vs Vista@Marineford|Mihawk vs Luffy@Marineford'),
    entry('Boa Hancock', 'hancock', 'Kuja', 'Ancienne esclave des Dragons célestes, Hancock devient impératrice d’Amazon Lily. Elle cache son passé et protège ses sœurs. Sa rencontre avec Luffy bouleverse sa méfiance ; elle l’aide à infiltrer Impel Down et le soutient pendant la guerre de Marineford.', 'A former Celestial Dragon slave, Hancock becomes Amazon Lily’s empress. She conceals her past and protects her sisters. Meeting Luffy challenges her distrust; she helps him enter Impel Down and supports him during Marineford.', 'Mero Mero no Mi — pétrification', 'Love-Love Fruit — petrification', 'Hancock vs Smoker@Marineford|Hancock vs Pacifista@Marineford|Hancock vs Blackbeard@AmazonLily', 'Sœur aînée de Sandersonia et Marigold.', 'Older sister of Sandersonia and Marigold.'),
    entry('Crocodile', 'crocodile', 'Cross Guild', 'Chef secret de Baroque Works, Crocodile manipule la guerre civile d’Alabasta pour trouver Pluton. Luffy fait échouer son plan. Évadé d’Impel Down, il intervient à Marineford puis fonde Cross Guild avec Mihawk, faisant des Marines des cibles de primes.', 'Baroque Works’ secret leader, Crocodile manipulates Alabasta’s civil war to find Pluton. Luffy stops his plan. Escaping Impel Down, he intervenes at Marineford, then establishes Cross Guild with Mihawk, placing bounties on Marines.', 'Suna Suna no Mi — sable et dessiccation', 'Sand-Sand Fruit — sand and dehydration', 'Crocodile vs Luffy@Alabasta|Crocodile vs Doflamingo@Marineford|Crocodile vs Akainu@Marineford'),
    entry('Donquixote Doflamingo', 'doflamingo', 'Donquixote', 'Né Dragon céleste, Doflamingo transforme sa rancune en empire criminel. Il s’empare de Dressrosa, vend des armes et fournit les SMILE à Kaido. Son frère Rosinante protège Law de lui ; l’alliance de Law et Luffy met fin à son règne.', 'Born a Celestial Dragon, Doflamingo turns his resentment into a criminal empire. He seizes Dressrosa, sells weapons and supplies Kaido with SMILEs. His brother Rosinante protects Law from him; Law and Luffy’s alliance ends his rule.', 'Ito Ito no Mi — fils et Birdcage', 'String-String Fruit — strings and Birdcage', 'Doflamingo vs Sanji@Dressrosa|Doflamingo vs Law@Dressrosa|Doflamingo vs Luffy@Dressrosa', 'Fils d’Homing ; frère de Rosinante.', 'Son of Homing; brother of Rosinante.'),
    entry('Bartholomew Kuma', 'kuma', 'Révolutionnaires', 'Issu du peuple des Buccaneers, Kuma subit l’esclavage puis devient révolutionnaire. Il élève Bonney et accepte les expériences de Vegapunk pour la sauver. Son corps sert de modèle aux Pacifistas ; à Sabaody, il disperse les Mugiwara pour les sauver.', 'Born among the Buccaneers, Kuma suffers slavery and later becomes a revolutionary. He raises Bonney and accepts Vegapunk’s experiments to save her. His body becomes the Pacifistas’ model; at Sabaody he scatters the Straw Hats to save them.', 'Nikyu Nikyu no Mi — répulsion', 'Paw-Paw Fruit — repulsion', 'Kuma vs Zoro@Thriller|Kuma vs Straw Hats@Sabaody|Kuma vs Saturn@Egghead', 'Père adoptif de Jewelry Bonney ; Ginny était sa compagne.', 'Adoptive father of Jewelry Bonney; Ginny was his partner.'),
    entry('Gecko Moria', 'moria', 'Thriller Bark', 'Après avoir perdu son équipage face à Kaido, Moria tente de remplacer ses compagnons par une armée de zombies. Il vole des ombres sur Thriller Bark et anime Oars. Luffy détruit son projet, puis Moria découvre que Teach a fait tuer Absalom.', 'After losing his crew to Kaido, Moria tries to replace his companions with a zombie army. He steals shadows on Thriller Bark and animates Oars. Luffy destroys his project; later Moria learns that Teach had Absalom killed.', 'Kage Kage no Mi — ombres et zombies', 'Shadow-Shadow Fruit — shadows and zombies', 'Moria vs Luffy@Thriller|Moria vs Jinbe@Marineford|Moria vs Kaido@Past'),
    entry('Trafalgar D. Water Law', 'law', 'Heart', 'Survivant de Flevance, Law est sauvé par Rosinante qui lui procure le fruit de l’Opération. Chirurgien et capitaine des Heart Pirates, il organise l’alliance contre Doflamingo puis Kaido. Son éveil aide Kid à vaincre Big Mom avant sa rencontre avec Teach.', 'A Flevance survivor, Law is saved by Rosinante, who obtains the Op-Op Fruit for him. A surgeon and Heart Pirates captain, he builds the alliance against Doflamingo and then Kaido. His awakening helps Kid defeat Big Mom before his encounter with Teach.', 'Ope Ope no Mi — ROOM et K-ROOM', 'Op-Op Fruit — ROOM and K-ROOM', 'Law vs Vergo@PunkHazard|Law vs Doflamingo@Dressrosa|Law and Kid vs Big Mom@Wano', 'Sa famille de Flevance est morte ; Rosinante l’a sauvé et élevé.', 'His Flevance family died; Rosinante saved and cared for him.'),
    entry('Eustass Kid', 'kid', 'Kid', 'Capitaine des Kid Pirates et membre de la Pire Génération, Kid rivalise avec Luffy. Emprisonné par Kaido, il retrouve Killer à Wano. L’éveil de son magnétisme permet de combattre Big Mom avec Law, mais sa confrontation ultérieure avec Shanks coûte très cher à son équipage.', 'Kid Pirates captain and a Worst Generation member, Kid rivals Luffy. Imprisoned by Kaido, he reunites with Killer in Wano. His awakened magnetism lets him fight Big Mom with Law, but his later confrontation with Shanks devastates his crew.', 'Jiki Jiki no Mi — magnétisme', 'Magnet-Magnet Fruit — magnetism', 'Kid vs Pacifista@Sabaody|Kid and Law vs Big Mom@Wano|Kid vs Shanks@Elbaf', 'Killer est son ami d’enfance et son partenaire de confiance.', 'Killer is his childhood friend and trusted partner.'),
    entry('Killer', 'killer', 'Kid', 'Combattant masqué des Kid Pirates, Killer reste loyal à Kid après la trahison de leur alliance. Forcé de manger un SMILE défectueux, il devient Kamazo à Wano. Il retrouve son capitaine, affronte les Empereurs et protège Kid contre le pouvoir de Hawkins.', 'The Kid Pirates’ masked fighter, Killer stays loyal to Kid after their alliance is betrayed. Forced to eat a failed SMILE, he becomes Kamazo in Wano. Reunited with his captain, he fights the Emperors and protects Kid from Hawkins’ power.', 'Punishers — lames rotatives', 'Punishers — rotating blades', 'Killer vs Zoro@Wano|Killer vs Kaido@Wano|Killer vs Hawkins@Wano'),
    entry('Carrot', 'carrot', 'Minks', 'Mink lapine de Zou, Carrot voyage clandestinement avec les Mugiwara vers Whole Cake Island. Pedro lui transmet sa confiance dans l’aube du monde. Son Sulong protège le Sunny durant la fuite ; à Wano, elle cherche à venger Pedro aux côtés de Wanda.', 'A rabbit Mink from Zou, Carrot secretly travels with the Straw Hats to Whole Cake Island. Pedro entrusts her with his faith in the world’s dawn. Her Sulong protects the Sunny during their escape; in Wano she seeks to avenge Pedro alongside Wanda.', 'Electro et Sulong', 'Electro and Sulong', 'Carrot vs Zoro@Zou|Carrot vs Brulee@WholeCake|Carrot vs Perospero@Wano'),
    entry('Jewelry Bonney', 'bonney', 'Bonney', 'Bonney prend la mer pour retrouver Kuma, son père adoptif. Son pouvoir modifie les âges et transforme les futurs possibles. À Egghead, elle découvre la mémoire de Kuma et la vérité sur ses sacrifices, tout en affrontant l’autorité des Dragons célestes.', 'Bonney sets sail to find Kuma, her adoptive father. Her power alters ages and transforms possible futures. At Egghead she discovers Kuma’s memories and the truth about his sacrifices while confronting Celestial Dragon authority.', 'Toshi Toshi no Mi — âges et futurs', 'Age-Age Fruit — ages and futures', 'Bonney vs Marines@Sabaody|Bonney vs Saturn@Egghead|Bonney vs Luffy@Egghead', 'Fille de Ginny ; élevée par Kuma.', 'Ginny’s daughter; raised by Kuma.'),
    entry('Capone Bege', 'bege', 'Fire Tank', 'Ancien chef de mafia de West Blue, Bege devient pirate et se rapproche de Big Mom. Son mariage avec Chiffon lui donne une famille qu’il protège farouchement. Il s’allie temporairement à Luffy pour préparer l’assassinat de Big Mom au mariage de Sanji.', 'A former West Blue mafia boss, Bege becomes a pirate and joins Big Mom’s network. Marriage to Chiffon gives him a family he fiercely protects. He temporarily allies with Luffy to plot Big Mom’s assassination at Sanji’s wedding.', 'Shiro Shiro no Mi — forteresse', 'Castle-Castle Fruit — fortress', 'Bege vs Pekoms@Zou|Bege vs Big Mom@WholeCake|Bege vs Oven@WholeCake', 'Époux de Chiffon et père de Pez.', 'Chiffon’s husband and Pez’s father.'),
    entry('Basil Hawkins', 'hawkins', 'Hawkins', 'Capitaine de la Pire Génération, Hawkins lit ses cartes pour calculer ses chances. Après l’arrivée de Kaido, il choisit la soumission et sert les Cent Bêtes à Wano. Ses poupées de paille détournent les blessures vers ses otages, jusqu’au duel avec Killer.', 'A Worst Generation captain, Hawkins reads cards to calculate his odds. After Kaido’s arrival he chooses submission and serves the Beast Pirates in Wano. His straw dolls transfer injuries to hostages until his duel with Killer.', 'Wara Wara no Mi — paille et poupées', 'Straw-Straw Fruit — straw and dolls', 'Hawkins vs Kizaru@Sabaody|Hawkins vs Zoro@Wano|Hawkins vs Killer@Wano'),
    entry('Scratchmen Apoo', 'apoo', 'On Air', 'Apoo dirige les On Air Pirates et cache sa fidélité à Kaido lors de l’alliance avec Kid. Sur Onigashima, ses attaques sonores menacent les adversaires qui peuvent l’entendre. Opportuniste, il cherche ensuite de nouvelles alliances lorsque la bataille tourne.', 'Apoo leads the On Air Pirates and conceals his loyalty to Kaido during his alliance with Kid. On Onigashima his sound attacks threaten opponents who can hear him. An opportunist, he looks for new alliances as the battle changes.', 'Oto Oto no Mi — attaques sonores', 'Tone-Tone Fruit — sound attacks', 'Apoo vs Kizaru@Sabaody|Apoo vs Kid@Wano|Apoo vs Zoro@Wano'),
    entry('X Drake', 'drake', 'SWORD', 'Ancien enfant de pirates devenu Marine, Drake se présente comme capitaine pirate pour infiltrer les Cent Bêtes. Membre de SWORD, il transmet des informations à Koby. Démasqué à Wano, il demande à combattre aux côtés de Luffy et affronte le CP0.', 'A pirate’s child who becomes a Marine, Drake poses as a pirate captain to infiltrate the Beast Pirates. As a SWORD member he passes information to Koby. Exposed in Wano, he asks to fight alongside Luffy and confronts CP0.', 'Zoan antique de l’allosaure', 'Ancient Allosaurus Zoan', 'Drake vs Pacifista@Sabaody|Drake vs Apoo@Wano|Drake vs CP0@Wano', 'Fils de Diez Barrels.', 'Son of Diez Barrels.'),
    entry('Urouge', 'urouge', 'Moines dépravés', 'Moine ailé et capitaine de la Pire Génération, Urouge combat à Sabaody avant de s’aventurer dans le Nouveau Monde. Il vainc Snack, un commandant de Big Mom, mais perd ensuite contre Cracker. Blessé, il se repose sur une île céleste.', 'A winged monk and Worst Generation captain, Urouge fights on Sabaody before entering the New World. He defeats Snack, a Big Mom commander, but later loses to Cracker. Wounded, he recovers on a sky island.', 'Conversion des blessures en force', 'Converting damage into strength', 'Urouge vs Pacifista@Sabaody|Urouge vs Snack@WholeCake|Urouge vs Cracker@WholeCake'),
    entry('Smoker', 'smoker', 'Marine', 'Marine de Loguetown, Smoker poursuit Luffy à travers Grand Line. Il refuse de confondre justice et propagande quand le Gouvernement lui attribue la victoire d’Alabasta. À Punk Hazard, il coopère avec les pirates pour comprendre la trahison de Vergo.', 'A Loguetown Marine, Smoker pursues Luffy through Grand Line. He refuses to confuse justice with propaganda when the Government credits him with Alabasta’s victory. At Punk Hazard he cooperates with pirates to expose Vergo’s betrayal.', 'Moku Moku no Mi — fumée', 'Smoke-Smoke Fruit — smoke', 'Smoker vs Luffy@Loguetown|Smoker vs Law@PunkHazard|Smoker vs Vergo@PunkHazard'),
    entry('Tashigi', 'tashigi', 'Marine', 'Épéiste et subordonnée de Smoker, Tashigi veut récupérer les lames célèbres utilisées par les criminels. Son apparence rappelle Kuina à Zoro, mais elle suit sa propre voie. Elle participe aux événements d’Alabasta et protège les enfants prisonniers de Caesar à Punk Hazard.', 'A swordswoman serving under Smoker, Tashigi wants to recover famous blades used by criminals. She resembles Kuina to Zoro but follows her own path. She takes part in Alabasta’s events and protects Caesar’s captive children at Punk Hazard.', 'Escrime et Haki de l’armement', 'Swordsmanship and Armament Haki', 'Tashigi vs Zoro@Loguetown|Tashigi vs Robin@Alabasta|Tashigi vs Monet@PunkHazard'),
    entry('Koby', 'koby', 'SWORD', 'Ancien garçon de corvée d’Alvida, Koby trouve grâce à Luffy le courage de devenir Marine. Garp l’entraîne et son Haki s’éveille à Marineford. Héros de Rocky Port et membre de SWORD, il apprend à protéger les autres malgré la peur.', 'Once Alvida’s cabin boy, Koby finds the courage to become a Marine through Luffy. Garp trains him and his Haki awakens at Marineford. A Rocky Port hero and SWORD member, he learns to protect others despite fear.', 'Rokushiki et Honesty Impact', 'Six Powers and Honesty Impact', 'Koby vs Luffy@Water7|Koby vs Luffy@Marineford|Koby vs Avalo Pizarro@Hachinosu'),
    entry('Izo', 'izo', 'Barbe Blanche', 'Ancien compagnon d’Oden, Izo quitte Wano avec son seigneur puis demeure parmi les Pirates de Barbe Blanche. Il revient soutenir les samouraïs contre Kaido. Sur Onigashima, il donne sa vie en affrontant deux agents du CP0 pour défendre l’alliance.', 'A former Oden companion, Izo leaves Wano with his lord and stays with Whitebeard’s pirates. He returns to support the samurai against Kaido. On Onigashima he dies fighting two CP0 agents to defend the alliance.', 'Pistolets renforcés au Haki', 'Haki-enhanced pistols', 'Izo vs Marines@Marineford|Izo vs Kaido@Wano|Izo vs CP0@Wano', 'Frère aîné de Kikunojo.', 'Kikunojo’s older brother.'),
    entry('Monkey D. Garp', 'garp', 'Marine', 'Héros de la Marine et rival de Roger, Garp refuse les promotions qui le placeraient sous les Dragons célestes. Il élève Luffy et Ace avec Dadan et entraîne Koby. À Hachinosu, il mène une opération pour sauver son élève capturé.', 'A Marine hero and Roger rival, Garp refuses promotions that would put him under the Celestial Dragons. He raises Luffy and Ace with Dadan and trains Koby. At Hachinosu he leads an operation to rescue his captured student.', 'Haki et Galaxy Impact', 'Haki and Galaxy Impact', 'Garp vs Don Chinjao@Past|Garp vs Marco@Marineford|Garp vs Kuzan@Hachinosu', 'Père de Dragon et grand-père de Luffy ; gardien d’Ace.', 'Dragon’s father and Luffy’s grandfather; Ace’s guardian.'),
    entry('Sengoku', 'sengoku', 'Marine', 'Ancien amiral puis amiral en chef, Sengoku dirige la Marine pendant la guerre de Marineford. Son fruit le transforme en Bouddha géant. Il élève Rosinante comme un fils et, après son départ du commandement, reste conseiller de la Marine.', 'A former admiral and fleet admiral, Sengoku commands the Marines during Marineford. His fruit transforms him into a giant Buddha. He treats Rosinante as a son and remains a Marine adviser after leaving command.', 'Zoan mythique du Bouddha', 'Mythical Buddha Zoan', 'Sengoku and Garp vs Shiki@Past|Sengoku vs Luffy@Marineford|Sengoku vs Blackbeard Pirates@Marineford', 'Rosinante est son fils de cœur.', 'Rosinante is his son figure.'),
    entry('Sakazuki', 'akainu', 'Marine', 'Amiral sous le nom d’Akainu, Sakazuki applique une justice absolue qui ne tolère aucun compromis. À Marineford, il tue Ace et poursuit Luffy. Son duel de dix jours contre Kuzan lui donne ensuite le poste d’amiral en chef et transforme Punk Hazard.', 'An admiral known as Akainu, Sakazuki follows uncompromising Absolute Justice. At Marineford he kills Ace and pursues Luffy. His ten-day duel with Kuzan later wins him fleet-admiral command and transforms Punk Hazard.', 'Magu Magu no Mi — magma', 'Magma-Magma Fruit — magma', 'Akainu vs Ace@Marineford|Akainu vs Whitebeard@Marineford|Akainu vs Aokiji@PunkHazard'),
    entry('Kuzan', 'aokiji', 'Barbe Noire', 'Ancien amiral Aokiji et élève de Garp, Kuzan remet en question la justice de la Marine après Ohara. Battu par Sakazuki pour le commandement, il quitte l’organisation et rejoint Teach. À Hachinosu, il affronte son ancien maître.', 'Former admiral Aokiji and Garp’s student, Kuzan questions Marine justice after Ohara. Defeated by Sakazuki for command, he leaves the organization and joins Teach. On Hachinosu he fights his former mentor.', 'Hie Hie no Mi — glace', 'Ice-Ice Fruit — ice', 'Aokiji vs Luffy@LongRing|Aokiji vs Akainu@PunkHazard|Kuzan vs Garp@Hachinosu'),
    entry('Borsalino', 'kizaru', 'Marine', 'Amiral connu comme Kizaru, Borsalino transforme la lumière en déplacement et en attaques. Il écrase les Supernovas à Sabaody avant l’intervention de Rayleigh. À Egghead, ses ordres contre Vegapunk le placent face aux liens personnels qu’il entretenait sur l’île.', 'The admiral known as Kizaru turns light into movement and attacks. He overwhelms the Supernovas on Sabaody before Rayleigh intervenes. On Egghead, orders against Vegapunk confront him with his personal bonds on the island.', 'Pika Pika no Mi — lumière', 'Glint-Glint Fruit — light', 'Kizaru vs Rayleigh@Sabaody|Kizaru vs Marco@Marineford|Kizaru vs Luffy@Egghead'),
    entry('Issho', 'fujitora', 'Marine', 'Amiral aveugle recruté après Marineford, Fujitora préfère protéger les civils que préserver les apparences du Gouvernement. À Dressrosa, il témoigne des crimes de Doflamingo et s’excuse publiquement. Il soutient l’abolition du système des Grands Corsaires.', 'A blind admiral recruited after Marineford, Fujitora values civilian safety over Government appearances. On Dressrosa he witnesses Doflamingo’s crimes and apologizes publicly. He supports ending the Warlord system.', 'Zushi Zushi no Mi — gravité', 'Press-Press Fruit — gravity', 'Fujitora vs Law@Dressrosa|Fujitora vs Sabo@Dressrosa|Fujitora vs Luffy@Dressrosa'),
    entry('Aramaki', 'ryokugyu', 'Marine', 'Nouvel amiral surnommé Ryokugyu, Aramaki suit une vision sévère de l’ordre mondial. Son pouvoir végétal absorbe les nutriments de ses cibles. Après la chute de Kaido, il arrive à Wano, affronte les défenseurs du pays puis recule face au Haki de Shanks.', 'The new admiral called Ryokugyu follows a harsh view of world order. His plant power drains nutrients from targets. After Kaido’s fall he arrives in Wano, fights its defenders and retreats before Shanks’ Haki.', 'Mori Mori no Mi — végétation', 'Woods-Woods Fruit — vegetation', 'Ryokugyu vs King and Queen@Wano|Ryokugyu vs Scabbards@Wano|Ryokugyu vs Momonosuke@Wano'),
    entry('Sentomaru', 'sentomaru', 'Science', 'Garde du corps de Vegapunk et commandant des Pacifistas, Sentomaru défend d’abord l’autorité de la Marine à Sabaody. À Egghead, il choisit de protéger celui qui l’a recueilli. Cette décision le conduit à affronter Lucci puis Kizaru.', 'Vegapunk’s bodyguard and a Pacifista commander, Sentomaru initially enforces Marine authority on Sabaody. On Egghead he chooses to protect the man who took him in. This decision leads him to fight Lucci and Kizaru.', 'Défense au Haki de l’armement', 'Armament Haki defence', 'Sentomaru vs Luffy@Sabaody|Sentomaru vs Lucci@Egghead|Sentomaru vs Kizaru@Egghead'),
    entry('Rob Lucci', 'lucci', 'CP', 'Assassin du CP9, Lucci infiltre Galley-La à Water Seven pour trouver Pluton. Sa défaite contre Luffy à Enies Lobby n’efface pas sa fidélité au Gouvernement. Revenu au CP0, il affronte les Mugiwara sur Egghead avec un Zoan éveillé.', 'A CP9 assassin, Lucci infiltrates Galley-La in Water Seven to find Pluton. Losing to Luffy at Enies Lobby does not end his Government loyalty. Returning with CP0, he fights the Straw Hats on Egghead with an awakened Zoan.', 'Rokushiki et Zoan du léopard', 'Six Powers and Leopard Zoan', 'Lucci vs Luffy@Enies|Lucci vs Luffy@Egghead|Lucci vs Zoro@Egghead'),
    entry('Kaku', 'kaku', 'CP', 'Agent du CP9 déguisé en charpentier, Kaku se fait connaître pour ses sauts et son habileté aux lames. Son fruit de la girafe transforme son style à Enies Lobby. Il rejoint ensuite le CP0 et revient face à Zoro sur Egghead.', 'A CP9 agent posing as a shipwright, Kaku is known for his jumps and blade skill. His giraffe fruit changes his fighting style at Enies Lobby. He later joins CP0 and faces Zoro again on Egghead.', 'Rokushiki et Zoan de la girafe', 'Six Powers and Giraffe Zoan', 'Kaku vs Zoro@Water7|Kaku vs Zoro@Enies|Kaku vs Zoro@Egghead'),
    entry('Jabra', 'jabra', 'CP', 'Agent du CP9 et rival de Kaku, Jabra utilise son Zoan du loup avec le Tekkai. Ses mensonges visent à déstabiliser l’adversaire avant l’attaque. À Enies Lobby, il menace Usopp puis affronte Sanji, dont le Diable Jambe dépasse sa défense.', 'A CP9 agent and Kaku rival, Jabra combines his wolf Zoan with Iron Body. His lies aim to unsettle opponents before he attacks. At Enies Lobby he threatens Usopp and then fights Sanji, whose Diable Jambe overcomes his defence.', 'Zoan du loup et Tekkai Kenpo', 'Wolf Zoan and Iron Body Kenpo', 'Jabra vs Usopp@Enies|Jabra vs Sanji@Enies|Jabra vs Pirates@Cover'),
    entry('Blueno', 'blueno', 'CP', 'Sous sa couverture de barman, Blueno espionne Water Seven pour le CP9. Le fruit des portes lui permet de créer des passages dans les murs et dans l’air. À Enies Lobby, il devient le premier adversaire sur lequel Luffy démontre son Gear Second.', 'Under a bartender cover, Blueno spies on Water Seven for CP9. The Door-Door Fruit lets him open passages through walls and air. On Enies Lobby he becomes the first opponent against whom Luffy demonstrates Gear Second.', 'Doa Doa no Mi et Rokushiki', 'Door-Door Fruit and Six Powers', 'Blueno vs Luffy@Water7|Blueno vs Sanji@SeaTrain|Blueno vs Luffy@Enies'),
    entry('Kalifa', 'kalifa', 'CP', 'Secrétaire d’Iceburg en apparence, Kalifa est une espionne du CP9. Après la révélation de sa mission, elle mange le fruit des bulles et apprend à nettoyer la force de ses adversaires. À Enies Lobby, Nami trouve comment neutraliser ses effets avec de l’eau.', 'Apparently Iceburg’s secretary, Kalifa is a CP9 spy. After exposing her mission she eats the Bubble-Bubble Fruit and learns to wash away opponents’ strength. On Enies Lobby Nami discovers that water can counter its effects.', 'Awa Awa no Mi — bulles', 'Bubble-Bubble Fruit — bubbles', 'Kalifa vs Luffy@Water7|Kalifa vs Sanji@Enies|Kalifa vs Nami@Enies'),
    entry('Kumadori', 'kumadori', 'CP', 'Agent du CP9 au comportement théâtral, Kumadori maîtrise le retour à la vie pour contrôler son corps et ses cheveux. À Enies Lobby, il menace Nami puis affronte Chopper. Le Monster Point du médecin renverse le duel.', 'A theatrical CP9 agent, Kumadori uses Life Return to control his body and hair. On Enies Lobby he threatens Nami before fighting Chopper. The doctor’s Monster Point overturns their battle.', 'Seimei Kikan et Rokushiki', 'Life Return and Six Powers', 'Kumadori vs Nami@Enies|Kumadori vs Chopper@Enies|Kumadori vs Pirates@Cover'),
    entry('Fukuro', 'fukuro', 'CP', 'Agent bavard du CP9, Fukuro mesure le Doriki de ses collègues mais révèle aussi leurs secrets. Son corps arrondi cache une grande maîtrise du Soru. Franky le combat à Enies Lobby et prouve que ses réserves de cola peuvent changer l’issue du duel.', 'A talkative CP9 agent, Fukuro measures his colleagues’ Doriki but also reveals their secrets. His rounded body hides strong Shave mastery. Franky fights him on Enies Lobby and shows how cola reserves can change their battle.', 'Rokushiki — Soru et Tekkai', 'Six Powers — Shave and Iron Body', 'Fukuro vs Franky@Enies|Fukuro vs Pirates@Cover'),
    entry('Vergo', 'vergo', 'Donquixote', 'Premier Corazon des Donquixote, Vergo infiltre la Marine et prend la tête du G-5. Sa loyauté à Doflamingo lui permet de cacher les crimes de Punk Hazard. Son Haki couvre tout son corps, mais Law finit par le trancher dans son ROOM.', 'The Donquixotes’ first Corazon, Vergo infiltrates the Marines and leads G-5. Loyalty to Doflamingo lets him conceal Punk Hazard’s crimes. His Haki covers his body, but Law finally cuts through him within his ROOM.', 'Haki intégral et bambou', 'Full-body Haki and bamboo weapon', 'Vergo vs Sanji@PunkHazard|Vergo vs Smoker@PunkHazard|Vergo vs Law@PunkHazard'),
    entry('Charlotte Katakuri', 'katakuri', 'Big Mom', 'Commandant de Big Mom, Katakuri cultive une image de grand frère invincible pour protéger sa famille. Son observation lui permet de voir brièvement l’avenir. Dans le monde des miroirs, le combat contre Luffy transforme leur rivalité en respect mutuel.', 'A Big Mom commander, Katakuri maintains an invincible older-brother image to protect his family. His Observation Haki sees briefly into the future. Fighting Luffy in the mirror world turns their rivalry into mutual respect.', 'Mochi Mochi no Mi et vision du futur', 'Mochi-Mochi Fruit and future sight', 'Katakuri vs Ichiji@WholeCake|Katakuri vs Luffy@WholeCake|Katakuri vs Vinsmoke@Cover', 'Fils de Linlin ; frère de la famille Charlotte.', 'Linlin’s son; a Charlotte family brother.'),
    entry('Charlotte Cracker', 'cracker', 'Big Mom', 'Commandant de Big Mom, Cracker cache son vrai corps derrière un soldat de biscuit et produit une armée de copies. Il affronte Luffy dans la Forêt des Tentations. Nami ramollit ses biscuits avec la pluie, permettant à Luffy d’utiliser Tankman.', 'A Big Mom commander, Cracker hides his body inside a biscuit soldier and produces an army of copies. He fights Luffy in the Seducing Woods. Nami softens his biscuits with rain, allowing Luffy to use Tankman.', 'Bisu Bisu no Mi — soldats de biscuit', 'Bis-Bis Fruit — biscuit soldiers', 'Cracker vs Urouge@WholeCake|Cracker vs Luffy@WholeCake|Cracker vs Kuzan@Cover', 'Fils de Charlotte Linlin.', 'Son of Charlotte Linlin.'),
    entry('Pica', 'pica', 'Donquixote', 'Lieutenant de Doflamingo, Pica contrôle les constructions de pierre de Dressrosa. Il transforme le palais en corps géant et menace les alliés de Luffy. Zoro découpe cette masse pour localiser son vrai corps et vaincre son Haki.', 'A Doflamingo officer, Pica controls Dressrosa’s stone buildings. He turns the palace into a giant body and threatens Luffy’s allies. Zoro cuts through the mass to locate his real body and overcome his Haki.', 'Ishi Ishi no Mi — pierre', 'Stone-Stone Fruit — stone', 'Pica vs Zoro@Dressrosa|Pica vs Luffy@Dressrosa|Pica vs King Riku’s allies@Dressrosa'),
    entry('Charlotte Perospero', 'perospero', 'Big Mom', 'Fils aîné de Big Mom, Perospero immobilise ses ennemis avec du bonbon. L’explosion de Pedro lui coûte un bras, qu’il remplace par du sucre. Il poursuit l’alliance à Wano, où Nekomamushi vient venger Pedro.', 'Big Mom’s eldest son, Perospero immobilizes enemies with candy. Pedro’s explosion costs him an arm, which he replaces with sugar. He pursues the alliance in Wano, where Nekomamushi seeks to avenge Pedro.', 'Pero Pero no Mi — bonbon', 'Lick-Lick Fruit — candy', 'Perospero vs Pedro@WholeCake|Perospero vs Carrot and Wanda@Wano|Perospero vs Nekomamushi@Wano', 'Fils aîné de Linlin.', 'Linlin’s eldest son.'),
    entry('Charlotte Oven', 'oven', 'Big Mom', 'Membre puissant de la famille Charlotte, Oven chauffe son corps et la mer environnante. Sur Cacao, il tente d’empêcher la fuite de Luffy et punit ceux qui aident Bege. Ses attaques mettent à l’épreuve la solidarité de Chiffon et de son père.', 'A powerful Charlotte family member, Oven heats his body and the surrounding sea. On Cacao he tries to prevent Luffy’s escape and punishes those helping Bege. His attacks test the loyalty of Chiffon and her father.', 'Netsu Netsu no Mi — chaleur', 'Heat-Heat Fruit — heat', 'Oven vs Sanji@WholeCake|Oven vs Bege@WholeCake|Oven vs Pekoms@WholeCake', 'Fils de Linlin ; frère de Katakuri et Daifuku.', 'Linlin’s son; brother of Katakuri and Daifuku.'),
    entry('Charlotte Daifuku', 'daifuku', 'Big Mom', 'Fils de Big Mom, Daifuku invoque un génie armé depuis son corps. Il participe au piège du mariage de Sanji puis à la poursuite du Sunny. La mobilité de Carrot en Sulong déjoue les attaques de sa flotte.', 'Big Mom’s son, Daifuku summons an armed genie from his body. He joins the trap at Sanji’s wedding and the Sunny’s pursuit. Carrot’s Sulong mobility outmaneuvers his fleet’s attacks.', 'Hoya Hoya no Mi — génie', 'Puff-Puff Fruit — genie', 'Daifuku vs Sanji@WholeCake|Daifuku vs Carrot@WholeCake|Daifuku vs Vinsmoke@WholeCake', 'Fils de Linlin ; frère de Katakuri et Oven.', 'Linlin’s son; brother of Katakuri and Oven.'),
    entry('Diamante', 'diamante', 'Donquixote', 'Lieutenant de Doflamingo et champion du Colisée Corrida, Diamante transforme les objets solides en formes flottantes. Responsable de la mort de Scarlett, il affronte Kyros devant Rebecca. Ce duel met fin à la souffrance de leur famille.', 'A Doflamingo officer and Corrida Colosseum champion, Diamante makes solid objects flutter. Responsible for Scarlett’s death, he fights Kyros in front of Rebecca. Their battle ends his hold over the family’s suffering.', 'Hira Hira no Mi — formes flottantes', 'Ripple-Ripple Fruit — fluttering forms', 'Diamante vs Sabo@Dressrosa|Diamante vs Rebecca@Dressrosa|Diamante vs Kyros@Dressrosa'),
    entry('King', 'king', 'Cent Bêtes', 'Dernier survivant connu du peuple lunaria, Alber rejoint Kaido après leur fuite d’un laboratoire. Sous le nom de King, il cache son visage et alterne une défense liée à sa flamme avec une vitesse supérieure. Zoro découvre ce mécanisme sur Onigashima.', 'The last known Lunarian survivor, Alber joins Kaido after they escape a laboratory. As King he hides his face and alternates flame-linked defence with greater speed. Zoro discovers this mechanism on Onigashima.', 'Zoan du ptéranodon et flammes lunarias', 'Pteranodon Zoan and Lunarian flames', 'King vs Sanji@Wano|King vs Marco@Wano|King vs Zoro@Wano'),
    entry('Queen', 'queen', 'Cent Bêtes', 'Scientifique anciennement lié à MADS, Queen combine son Zoan du brachiosaure avec un corps cyborg. Il dirige Udon et utilise des virus pour contrôler les prisonniers. À Onigashima, Chopper combat son épidémie avant que Sanji ne le batte.', 'A scientist formerly associated with MADS, Queen combines his Brachiosaurus Zoan with a cyborg body. He runs Udon and uses viruses to control prisoners. On Onigashima Chopper fights his epidemic before Sanji defeats him.', 'Zoan du brachiosaure et armes cyborg', 'Brachiosaurus Zoan and cyborg weapons', 'Queen vs Big Mom@Wano|Queen vs Chopper@Wano|Queen vs Sanji@Wano'),
    entry('Jack', 'jack', 'Cent Bêtes', 'Commandant de Kaido et homme-poisson, Jack cherche Raizo sur Zou et emploie le gaz de Caesar contre les Minks. Son endurance prolonge les affrontements contre leurs deux dirigeants. À Wano, Inuarashi règle enfin les comptes de Zou.', 'A Kaido commander and fish-man, Jack hunts Raizo on Zou and uses Caesar’s gas against the Minks. His endurance prolongs battles against both their rulers. In Wano Inuarashi finally settles Zou’s score.', 'Zoan antique du mammouth', 'Ancient Mammoth Zoan', 'Jack vs Inuarashi@Zou|Jack vs Nekomamushi@Zou|Jack vs Inuarashi@Wano'),
    entry('Ulti', 'ulti', 'Cent Bêtes', 'Tobiroppo des Cent Bêtes, Ulti protège son petit frère Page One et défie même les paroles de Kaido. Son Zoan du pachycéphalosaure renforce ses coups de tête. À Onigashima, elle poursuit Nami et Usopp, puis affronte Big Mom.', 'A Beast Pirates Tobiroppo, Ulti protects her younger brother Page One and even challenges Kaido’s words. Her Pachycephalosaurus Zoan strengthens her headbutts. On Onigashima she pursues Nami and Usopp and confronts Big Mom.', 'Zoan du pachycéphalosaure — Ulti Mortar', 'Pachycephalosaurus Zoan — Ulti Mortar', 'Ulti vs Luffy@Wano|Ulti vs Yamato@Wano|Ulti vs Nami@Wano', 'Sœur aînée de Page One.', 'Page One’s older sister.'),
    entry('Page One', 'page_one', 'Cent Bêtes', 'Frère d’Ulti et Tobiroppo, Page One prend la forme d’un spinosaure. Il affronte Sanji dans la capitale de Wano puis chasse Nami et Usopp sur Onigashima. Son attaque contre Tama provoque l’intervention de Big Mom.', 'Ulti’s brother and a Tobiroppo, Page One transforms into a Spinosaurus. He fights Sanji in Wano’s capital, then hunts Nami and Usopp on Onigashima. His attack on Tama brings Big Mom’s intervention.', 'Zoan antique du spinosaure', 'Ancient Spinosaurus Zoan', 'Page One vs Sanji@Wano|Page One vs Usopp@Wano|Page One vs Big Mom@Wano', 'Frère cadet d’Ulti.', 'Ulti’s younger brother.'),
    entry('Who’s-Who', 'whos_who', 'Cent Bêtes', 'Ancien agent du CP9, Who’s-Who est emprisonné après le vol du fruit transporté par son navire. Il rejoint ensuite Kaido et conserve sa rancune envers Shanks. À Onigashima, son combat contre Jinbe dévoile ce passé et sa connaissance du nom de Nika.', 'A former CP9 agent, Who’s-Who is imprisoned after the fruit carried on his ship is stolen. He later joins Kaido and keeps his resentment toward Shanks. On Onigashima his fight with Jinbe reveals his past and knowledge of Nika’s name.', 'Zoan du tigre à dents de sabre et Rokushiki', 'Saber-toothed Tiger Zoan and Six Powers', 'Who’s-Who vs Jinbe@Wano'),
    entry('Sasaki', 'sasaki', 'Cent Bêtes', 'Ancien capitaine pirate devenu Tobiroppo, Sasaki mène les troupes cuirassées de Kaido. Son Zoan du tricératops renforce sa charge et sa défense. Franky l’affronte dans le General Franky et doit combiner plusieurs armes pour gagner.', 'A former pirate captain turned Tobiroppo, Sasaki commands Kaido’s armoured troops. His Triceratops Zoan strengthens his charge and defence. Franky fights him in General Franky and combines multiple weapons to win.', 'Zoan antique du tricératops', 'Ancient Triceratops Zoan', 'Sasaki vs Yamato@Wano|Sasaki vs Franky@Wano'),
    entry('Black Maria', 'black_maria', 'Cent Bêtes', 'Tobiroppo installée dans le château de Kaido, Black Maria piège Sanji avec ses toiles. Robin et Brook viennent le libérer. Son Zoan d’araignée et ses illusions affrontent la décision de Robin de protéger les compagnons qui l’ont sauvée.', 'A Tobiroppo based in Kaido’s castle, Black Maria traps Sanji in her webs. Robin and Brook come to free him. Her Spider Zoan and illusions challenge Robin’s resolve to protect the friends who saved her.', 'Zoan antique d’araignée et toiles', 'Ancient Spider Zoan and webs', 'Black Maria vs Sanji@Wano|Black Maria vs Robin@Wano'),
    entry('Kinemon', 'kinemon', 'Kozuki', 'Vassal d’Oden et chef des Fourreaux rouges, Kinemon voyage vingt ans dans le futur grâce à Toki. À Punk Hazard, il retrouve Momonosuke avec l’aide des Mugiwara. Il rassemble ensuite les alliés de Wano pour venger son seigneur et libérer le pays.', 'An Oden retainer and Scabbards leader, Kinemon travels twenty years into the future through Toki. On Punk Hazard he reunites with Momonosuke with the Straw Hats’ help. He then gathers Wano’s allies to avenge his lord and free the country.', 'Escrime du feu et Fuku Fuku no Mi', 'Foxfire swordsmanship and Garb-Garb Fruit', 'Kinemon vs Dragon@PunkHazard|Kinemon vs Kaido@Wano|Kinemon vs Ryokugyu@Wano', 'Époux d’O-Tsuru ; vassal d’Oden.', 'O-Tsuru’s husband; Oden’s retainer.'),
    entry('Dellinger', 'dellinger', 'Donquixote', 'Combattant des Donquixote élevé par Giolla, Dellinger mêle une force d’homme-poisson à des coups de talon. Il poursuit Bellamy sur ordre de Doflamingo et affronte les gladiateurs de Dressrosa. Hakuba met fin à sa série de victoires.', 'A Donquixote fighter raised by Giolla, Dellinger combines fish-man strength with heel kicks. He hunts Bellamy on Doflamingo’s orders and fights Dressrosa’s gladiators. Hakuba ends his winning streak.', 'Force d’homme-poisson et coups de talon', 'Fish-man strength and heel kicks', 'Dellinger vs Bellamy@Dressrosa|Dellinger vs Ideo@Dressrosa|Dellinger vs Hakuba@Dressrosa', 'Élevé par Giolla au sein de la famille Donquixote.', 'Raised by Giolla within the Donquixote family.'),
    entry('Kozuki Oden', 'oden', 'Kozuki', 'Seigneur de Kuri, Oden quitte Wano avec Barbe Blanche puis voyage avec Roger jusqu’à Laugh Tale. Il découvre la nécessité d’ouvrir son pays. De retour chez lui, il défie Kaido et Orochi avant de sauver ses vassaux lors de son exécution.', 'Kuri’s lord, Oden leaves Wano with Whitebeard and later sails with Roger to Laugh Tale. He learns why his country must open its borders. Returning home, he challenges Kaido and Orochi and saves his retainers during his execution.', 'Oden Nitoryu — Enma et Ame no Habakiri', 'Oden Two-Sword Style — Enma and Ame no Habakiri', 'Oden vs Whitebeard@Past|Oden vs Roger@Past|Oden vs Kaido@Wano', 'Époux de Toki ; père de Momonosuke et Hiyori.', 'Toki’s husband; father of Momonosuke and Hiyori.'),
    entry('Yamato', 'yamato', 'Wano', 'Enfant de Kaido, Yamato admire Oden après avoir assisté à son exécution et lu son journal. Les chaînes imposées par son père ne brisent pas cette volonté. Yamato aide Luffy sur Onigashima et protège Wano après la chute des Cent Bêtes.', 'Kaido’s child, Yamato admires Oden after witnessing his execution and reading his journal. Kaido’s chains do not break that resolve. Yamato helps Luffy on Onigashima and protects Wano after the Beast Pirates’ fall.', 'Zoan mythique d’Okuchi no Makami', 'Mythical Okuchi-no-Makami Zoan', 'Yamato vs Ace@Past|Yamato vs Kaido@Wano|Yamato vs Ryokugyu@Wano', 'Enfant de Kaido ; ami d’Ace.', 'Kaido’s child; Ace’s friend.'),
    entry('Kanjuro', 'kanjuro', 'Kurozumi', 'Présenté comme un vassal d’Oden, Kanjuro joue ce rôle tout en espionnant pour Orochi. Son talent de peintre est bien supérieur à ce qu’il montre à ses compagnons. Sa trahison menace Momonosuke et l’assaut d’Onigashima.', 'Presented as Oden’s retainer, Kanjuro plays that role while spying for Orochi. His painting skill greatly exceeds what he shows his companions. His betrayal threatens Momonosuke and the Onigashima raid.', 'Fude Fude no Mi — dessins vivants', 'Brush-Brush Fruit — living drawings', 'Kanjuro vs Scabbards@Wano|Kanjuro vs Kikunojo@Wano|Kanjuro vs Kinemon@Wano', 'Membre du clan Kurozumi.', 'A member of the Kurozumi family.'),
    entry('Raizo', 'raizo', 'Kozuki', 'Ninja au service d’Oden, Raizo est caché sur Zou par les Minks malgré l’invasion de Jack. Il aide Luffy à Udon puis rejoint les Fourreaux rouges contre Kaido. Ses parchemins permettent aussi de combattre l’incendie du château d’Onigashima.', 'A ninja serving Oden, Raizo is hidden on Zou by the Minks despite Jack’s invasion. He helps Luffy in Udon and joins the Scabbards against Kaido. His scrolls also help fight the fire in Onigashima’s castle.', 'Maki Maki no Mi — parchemins', 'Scroll-Scroll Fruit — scrolls', 'Raizo vs Kaido@Wano|Raizo vs Fukurokuju@Wano|Raizo vs Ryokugyu@Wano'),
    entry('Kikunojo', 'kikunojo', 'Kozuki', 'Samouraï des Fourreaux rouges et sœur d’Izo, Kiku traverse vingt ans avec les compagnons envoyés par Toki. Elle retrouve les alliés de son seigneur sous sa couverture de serveuse. À Onigashima, sa loyauté est mise à l’épreuve par la trahison de Kanjuro.', 'A Scabbards samurai and Izo’s sister, Kiku crosses twenty years with the companions sent by Toki. Under a waitress cover she reunites with her lord’s allies. On Onigashima Kanjuro’s betrayal tests her loyalty.', 'Escrime de samouraï', 'Samurai swordsmanship', 'Kikunojo vs Kanjuro@Wano|Kikunojo vs Kaido@Wano|Kikunojo vs Gifters@Wano', 'Sœur cadette d’Izo.', 'Izo’s younger sister.'),
    entry('Ashura Doji', 'Shutenmaru', 'Kozuki', 'Ancien bandit de Kuri vaincu par Oden, Ashura Doji devient l’un de ses vassaux. Resté à Wano pendant vingt ans, il perd confiance dans le retour promis de ses compagnons. Il rejoint pourtant leur combat et protège les autres d’un piège de Kanjuro.', 'A former Kuri bandit defeated by Oden, Ashura Doji becomes his retainer. Remaining in Wano for twenty years weakens his trust in his companions’ promised return. He nevertheless joins their battle and shields them from Kanjuro’s trap.', 'Escrime des Fourreaux rouges', 'Scabbards swordsmanship', 'Ashura Doji vs Oden@Past|Ashura Doji vs Jack@Wano|Ashura Doji vs Kaido@Wano'),
    entry('Inuarashi', 'inuarashi', 'Minks', 'Mink chien et souverain diurne de Zou, Inuarashi a suivi Oden sur les navires de Barbe Blanche et Roger. Il protège Raizo pendant l’invasion de Jack. À Wano, il retrouve les Fourreaux rouges et utilise le Sulong pour venger les souffrances de Zou.', 'A canine Mink and Zou’s daytime ruler, Inuarashi followed Oden aboard Whitebeard’s and Roger’s ships. He protects Raizo during Jack’s invasion. In Wano he reunites with the Scabbards and uses Sulong to avenge Zou’s suffering.', 'Electro, Sulong et escrime', 'Electro, Sulong and swordsmanship', 'Inuarashi vs Jack@Zou|Inuarashi vs Kaido@Wano|Inuarashi vs Jack@Wano'),
    entry('Nekomamushi', 'nekomamushi', 'Minks', 'Mink félin et souverain nocturne de Zou, Nekomamushi partage le passé d’Inuarashi auprès d’Oden. Jack lui coûte une main lors de l’invasion. Il cherche Marco pour l’alliance et revient à Wano pour combattre Kaido puis venger Pedro.', 'A feline Mink and Zou’s nighttime ruler, Nekomamushi shares Inuarashi’s past with Oden. Jack costs him a hand during the invasion. He seeks Marco for the alliance and returns to Wano to fight Kaido and avenge Pedro.', 'Electro et Sulong', 'Electro and Sulong', 'Nekomamushi vs Jack@Zou|Nekomamushi vs Kaido@Wano|Nekomamushi vs Perospero@Wano'),
    entry('Denjiro', 'denjiro', 'Kozuki', 'Ancien vassal d’Oden, Denjiro survit à sa mort et prend l’identité de Kyoshiro. Il infiltre le cercle d’Orochi tout en protégeant Hiyori. Lorsque les samouraïs se rassemblent, il révèle son identité et participe à la libération de Wano.', 'Oden’s former retainer, Denjiro survives his death and adopts the identity Kyoshiro. He infiltrates Orochi’s circle while protecting Hiyori. When the samurai gather he reveals his identity and helps liberate Wano.', 'Escrime et infiltration', 'Swordsmanship and infiltration', 'Denjiro vs Zoro@Wano|Denjiro vs Kaido@Wano|Denjiro vs Orochi@Wano'),
    entry('Kawamatsu', 'kawamatsu', 'Kozuki', 'Homme-poisson recueilli par Oden, Kawamatsu se fait passer pour un kappa pour échapper aux préjugés. Il protège Hiyori après la chute du clan Kozuki. Emprisonné à Udon, il retrouve ensuite les Fourreaux rouges pour l’assaut contre Kaido.', 'A fish-man taken in by Oden, Kawamatsu poses as a kappa to escape prejudice. He protects Hiyori after the Kozuki clan’s fall. Imprisoned in Udon, he later rejoins the Scabbards for the raid against Kaido.', 'Escrime et sumo', 'Swordsmanship and sumo', 'Kawamatsu vs Udon guards@Wano|Kawamatsu vs Kaido@Wano|Kawamatsu vs Ryokugyu@Wano'),
    entry('Arlong', 'arlong', 'Arlong', 'Ancien membre des Pirates du Soleil, Arlong transforme sa haine des humains en oppression d’East Blue. Il impose un tribut à Cocoyasi et exploite les cartes de Nami. Luffy détruit Arlong Park et met fin à son contrôle sur le village.', 'A former Sun Pirate, Arlong turns hatred of humans into oppression in East Blue. He taxes Cocoyasi and exploits Nami’s maps. Luffy destroys Arlong Park and ends his control over the village.', 'Force d’homme-poisson et dents régénérables', 'Fish-man strength and regrowing teeth', 'Arlong vs Zoro@EastBlue|Arlong vs Sanji@EastBlue|Arlong vs Luffy@EastBlue', 'Frère de Shirley.', 'Shyarly’s brother.'),
    entry('Kuro', 'kuro', 'Black Cat', 'Capitaine des Black Cat Pirates, Kuro simule sa mort pour vivre sous le nom de Klahadore. Il prépare l’assassinat de Kaya afin de prendre son héritage. Usopp et Luffy découvrent son plan ; sa vitesse finit par menacer même ses propres hommes.', 'The Black Cat Pirates’ captain, Kuro fakes his death to live as Klahadore. He plots Kaya’s murder to steal her inheritance. Usopp and Luffy uncover the plan; his speed eventually endangers even his own crew.', 'Shakushi — vitesse et griffes', 'Out of the Bag — speed and claws', 'Kuro vs Luffy@EastBlue|Kuro vs Black Cat Pirates@EastBlue'),
    entry('Don Krieg', 'krieg', 'Krieg', 'Chef d’une immense flotte d’East Blue, Krieg revient affamé de Grand Line après sa rencontre avec Mihawk. Il tente de s’emparer du Baratie malgré l’aide reçue. Armure, armes cachées et gaz toxique soutiennent son idée que la puissance matérielle décide de tout.', 'Leader of a vast East Blue fleet, Krieg returns starving from Grand Line after encountering Mihawk. Despite receiving help he tries to seize the Baratie. Armour, hidden weapons and poison gas support his belief that equipment determines victory.', 'Armure, lance explosive et MH5', 'Armour, explosive spear and MH5', 'Don Krieg vs Mihawk@EastBlue|Don Krieg vs Luffy@EastBlue|Don Krieg vs Gin@EastBlue'),
    entry('Hatchan', 'hatchan', 'Sun Pirates', 'Homme-poisson pieuvre, Hatchan sert Arlong et affronte Zoro avec six sabres. Après sa défaite, il change de vie et ouvre un restaurant avec Camie. À Sabaody, il aide les Mugiwara et leur montre les conséquences de la discrimination envers les hommes-poissons.', 'An octopus fish-man, Hatchan serves Arlong and fights Zoro with six swords. After defeat he changes his life and opens a restaurant with Camie. On Sabaody he helps the Straw Hats and shows them the consequences of discrimination against fish-men.', 'Escrime à six sabres', 'Six-Sword Style', 'Hatchan vs Zoro@EastBlue|Hatchan vs Macro Pirates@Cover'),
    entry('Alvida', 'alvida', 'Buggy', 'Capitaine pirate qui exploite Koby, Alvida perd contre Luffy au début du voyage. Après avoir mangé le fruit glissant, elle change d’apparence mais conserve son ambition. Elle s’allie à Baggy pour poursuivre Luffy à Loguetown.', 'A pirate captain who exploits Koby, Alvida loses to Luffy at the start of his voyage. After eating the Slip-Slip Fruit her appearance changes but her ambition remains. She allies with Buggy to pursue Luffy in Loguetown.', 'Sube Sube no Mi — surface glissante', 'Slip-Slip Fruit — slippery body', 'Alvida vs Luffy@EastBlue|Alvida and Buggy vs Luffy@Loguetown'),
    entry('Enel', 'enel', 'Skypiea', 'Maître autoproclamé de Skypiea, Enel combine la foudre avec son Mantra pour surveiller l’île. Il veut atteindre la Lune à bord du Maxim et détruit ceux qui gênent ce projet. Le corps de caoutchouc de Luffy révèle la limite inattendue de son pouvoir.', 'Skypiea’s self-proclaimed god, Enel combines lightning with Mantra to watch the island. He seeks the Moon aboard the Maxim and destroys those obstructing him. Luffy’s rubber body reveals an unexpected limit to his power.', 'Goro Goro no Mi et Mantra', 'Rumble-Rumble Fruit and Mantra', 'Enel vs Zoro@Skypiea|Enel vs Wyper@Skypiea|Enel vs Luffy@Skypiea'),
    entry('Wapol', 'wapol', 'Drum', 'Ancien roi de Drum, Wapol fuit son royaume puis tente de reprendre son château. Son pouvoir avale et combine objets et personnes. Battu par Luffy, il découvre ensuite un nouvel alliage et reconstruit une fortune loin de Drum.', 'Drum’s former king, Wapol flees his kingdom and then tries to reclaim his castle. His power swallows and combines objects and people. Defeated by Luffy, he later discovers a new alloy and builds a fortune away from Drum.', 'Baku Baku no Mi — ingestion et fusion', 'Munch-Munch Fruit — eating and combining', 'Wapol vs Luffy@Drum|Wapol vs Chopper@Drum|Wapol vs Dalton@Drum'),
    entry('Daz Bonez', 'mr1', 'Cross Guild', 'Agent Mr. 1 de Baroque Works, Daz Bonez transforme son corps en lames d’acier. Zoro doit apprendre à trancher l’acier pour le vaincre à Alabasta. Daz reste fidèle à Crocodile après Impel Down et rejoint son nouvel empire.', 'Baroque Works agent Mr. 1, Daz Bonez turns his body into steel blades. Zoro must learn to cut steel to defeat him in Alabasta. Daz remains loyal to Crocodile after Impel Down and joins his new enterprise.', 'Supa Supa no Mi — lames d’acier', 'Dice-Dice Fruit — steel blades', 'Daz Bonez vs Zoro@Alabasta|Daz Bonez vs Luffy@Marineford|Daz Bonez vs Mihawk@Marineford'),
    entry('Bentham', 'mr2', 'Baroque Works', 'Sous le nom de Mr. 2 Bon Clay, Bentham combine danse, combat et imitation des visages. Après son duel contre Sanji, il se lie aux Mugiwara. À Impel Down, il risque sa vie pour Luffy puis reste derrière pour permettre l’évasion.', 'As Mr. 2 Bon Clay, Bentham combines dance, combat and copied faces. After fighting Sanji he befriends the Straw Hats. At Impel Down he risks his life for Luffy and stays behind to enable the escape.', 'Mane Mane no Mi et Okama Kenpo', 'Clone-Clone Fruit and Okama Kenpo', 'Bon Clay vs Sanji@Alabasta|Bon Clay vs Minotaurus@Impel|Bon Clay vs Magellan@Impel'),
    entry('Galdino', 'mr3', 'Cross Guild', 'Agent Mr. 3 de Baroque Works, Galdino immobilise les géants de Little Garden avec sa cire. Prisonnier d’Impel Down, il aide Luffy contre Magellan et fabrique la clé qui libère Ace à Marineford. Il accompagne ensuite Baggy.', 'Baroque Works agent Mr. 3, Galdino traps Little Garden’s giants with wax. Imprisoned at Impel Down, he helps Luffy against Magellan and makes the key that frees Ace at Marineford. He later follows Buggy.', 'Doru Doru no Mi — cire', 'Wax-Wax Fruit — wax', 'Mr 3 vs Luffy@LittleGarden|Mr 3 vs Brogy@LittleGarden|Mr 3 and Luffy vs Magellan@Impel'),
    entry('Perona', 'perona', 'Thriller Bark', 'Commandante des zombies de Moria, Perona utilise des fantômes qui enlèvent toute confiance à leurs victimes. Usopp résiste grâce à son pessimisme. Envoyée chez Mihawk par Kuma, elle aide Zoro pendant sa convalescence avant de chercher Moria.', 'Moria’s zombie commander, Perona uses ghosts that drain victims’ confidence. Usopp resists through his pessimism. Sent to Mihawk’s home by Kuma, she helps Zoro recover before seeking Moria.', 'Horo Horo no Mi — fantômes', 'Hollow-Hollow Fruit — ghosts', 'Perona vs Straw Hats@Thriller|Perona vs Usopp@Thriller|Perona vs Kuma@Thriller'),
    entry('Absalom', 'Absalom', 'Thriller Bark', 'Commandant de Thriller Bark, Absalom rend son corps invisible pour espionner et attaquer. Il tente d’imposer un mariage à Nami, qui le combat avec Sanji. Plus tard, sa disparition sur Hachinosu révèle que Shiryu a obtenu son fruit.', 'A Thriller Bark commander, Absalom makes himself invisible to spy and attack. He tries to force Nami into marriage; she fights him alongside Sanji. His later disappearance on Hachinosu reveals that Shiryu has obtained his fruit.', 'Suke Suke no Mi — invisibilité', 'Clear-Clear Fruit — invisibility', 'Absalom vs Sanji@Thriller|Absalom vs Nami@Thriller'),
    entry('Hody Jones', 'hody', 'New Fish-Man Pirates', 'Hody hérite de la haine d’Arlong sans avoir subi lui-même les torts qu’il prétend venger. Il veut renverser Neptune et attaque les humains comme les hommes-poissons qui les défendent. Les stéroïdes énergétiques renforcent sa force en détruisant sa santé.', 'Hody inherits Arlong’s hatred without personally suffering the wrongs he claims to avenge. He seeks to overthrow Neptune and attacks humans and fish-men who defend them. Energy Steroids increase his strength while destroying his health.', 'Karaté des hommes-poissons et stéroïdes', 'Fish-Man Karate and Energy Steroids', 'Hody Jones vs Zoro@Fishman|Hody Jones vs Neptune@Fishman|Hody Jones vs Luffy@Fishman'),
    entry('Vander Decken IX', 'vander_decken', 'Flying Pirates', 'Capitaine des Flying Pirates, Decken marque ses cibles pour que les objets lancés les poursuivent. Obsédé par Shirahoshi, il lui impose une menace permanente. Son alliance avec Hody conduit finalement au lancement de l’arche Noah vers l’île.', 'The Flying Pirates’ captain, Decken marks targets so thrown objects chase them. Obsessed with Shirahoshi, he subjects her to constant threats. His alliance with Hody eventually leads him to throw the ark Noah toward the island.', 'Mato Mato no Mi — ciblage', 'Mark-Mark Fruit — targeting', 'Vander Decken vs Luffy@Fishman|Vander Decken vs Hody Jones@Fishman'),
    entry('Rebecca', 'rebecca', 'Dressrosa', 'Petite-fille du roi Riku, Rebecca grandit sous l’oppression de Doflamingo avec le soldat jouet, son père Kyros dont l’existence a été effacée. Au Colisée, elle esquive plutôt que de tuer. La libération de Dressrosa lui rend sa famille.', 'King Riku’s granddaughter, Rebecca grows up under Doflamingo with the toy soldier, her father Kyros whose existence was erased. In the Colosseum she evades rather than kills. Dressrosa’s liberation restores her family.', 'Escrime défensive et Haki de l’observation', 'Defensive swordsmanship and Observation Haki', 'Rebecca vs Meadows@Dressrosa|Rebecca vs Hakuba@Dressrosa|Rebecca vs Diamante@Dressrosa', 'Fille de Kyros et Scarlett ; petite-fille de Riku.', 'Daughter of Kyros and Scarlett; Riku’s granddaughter.'),
    entry('Cavendish', 'cavendish', 'Beautiful Pirates', 'Capitaine des Beautiful Pirates, Cavendish jalouse d’abord la renommée des Supernovas. Son sommeil réveille Hakuba, une personnalité meurtrière d’une vitesse exceptionnelle. À Dressrosa, il protège pourtant les alliés de Luffy et devient membre de sa Grande Flotte.', 'The Beautiful Pirates’ captain, Cavendish initially envies the Supernovas’ fame. Sleep awakens Hakuba, a murderous personality with extraordinary speed. On Dressrosa he nevertheless protects Luffy’s allies and joins his Grand Fleet.', 'Durandal et vitesse de Hakuba', 'Durandal and Hakuba’s speed', 'Cavendish vs Don Chinjao@Dressrosa|Hakuba vs Dellinger@Dressrosa|Cavendish vs Gladius@Dressrosa'),
    entry('Bartolomeo', 'bartolomeo', 'Barto Club', 'Ancien chef de gang d’East Blue, Bartolomeo devient un admirateur de Luffy après Loguetown. Ses barrières font de lui un combattant redoutable au Colisée Corrida. Il protège Robin contre Gladius puis jure fidélité à Luffy dans sa Grande Flotte.', 'A former East Blue gang leader, Bartolomeo becomes a Luffy admirer after Loguetown. His barriers make him formidable in the Corrida Colosseum. He protects Robin from Gladius and pledges loyalty to Luffy’s Grand Fleet.', 'Bari Bari no Mi — barrières', 'Barrier-Barrier Fruit — barriers', 'Bartolomeo vs Hack@Dressrosa|Bartolomeo vs Elizabello@Dressrosa|Bartolomeo vs Gladius@Dressrosa'),
    entry('Sai', 'sai', 'Happo Navy', 'Petit-fils de Chinjao et héritier de la Happo Navy, Sai participe au Colisée Corrida. Les combats contre les Donquixote font mûrir sa force et ses choix personnels. Il reprend le commandement, épouse Baby 5 et rejoint la Grande Flotte de Luffy.', 'Chinjao’s grandson and Happo Navy heir, Sai joins the Corrida Colosseum. Fighting the Donquixotes matures his strength and personal choices. He takes command, marries Baby 5 and joins Luffy’s Grand Fleet.', 'Hasshoken — ondes de choc', 'Hasshoken — shock waves', 'Sai vs Ideo@Dressrosa|Sai vs Baby 5@Dressrosa|Sai vs Lao G@Dressrosa', 'Petit-fils de Chinjao, frère de Boo, époux de Baby 5.', 'Chinjao’s grandson, Boo’s brother and Baby 5’s husband.'),
    entry('Don Chinjao', 'chinjao', 'Happo Navy', 'Ancien chef de la Happo Navy, Chinjao perd sa tête pointue et l’accès à son trésor après son duel contre Garp. Il reporte sa rancune sur Luffy au Colisée. Leur combat restaure sa tête, puis ses petits-fils prennent leur place dans une nouvelle génération.', 'The Happo Navy’s former leader, Chinjao loses his pointed head and access to his treasure after fighting Garp. He directs his resentment at Luffy in the Colosseum. Their battle restores his head, and his grandsons take their place in a new generation.', 'Hasshoken et Haki des Rois', 'Hasshoken and Conqueror’s Haki', 'Chinjao vs Garp@Past|Chinjao vs Luffy@Dressrosa|Chinjao vs Lao G@Dressrosa', 'Grand-père de Sai et Boo.', 'Grandfather of Sai and Boo.')
  ];
  const dbz = [
    entry('Piccolo', 'Piccolo', 'Guerriers Z', 'Né de Piccolo Daimao, Piccolo devient d’abord le rival de Goku. L’arrivée des Saiyans le conduit à entraîner Gohan et à donner sa vie pour lui. Ses fusions avec Nail puis Kami renforcent sa puissance sans effacer son rôle de mentor.', 'Born from King Piccolo, Piccolo first becomes Goku’s rival. The Saiyans’ arrival leads him to train Gohan and give his life for him. Fusing with Nail and then Kami increases his power without ending his role as a mentor.', 'Makankosappo et régénération namek', 'Special Beam Cannon and Namekian regeneration', 'Piccolo vs Raditz@Saiyan|Piccolo vs Frieza@Namek|Piccolo vs Android 17@Android', 'Issu de Piccolo Daimao ; Gohan est son élève.', 'Born from King Piccolo; Gohan is his student.'),
    entry('Krilin', 'Krillin', 'Guerriers Z', 'Condisciple de Goku chez Tortue Géniale, Krilin devient l’un des défenseurs les plus fidèles de la Terre. Il aide Gohan sur Namek et affronte les cyborgs malgré l’écart de puissance. Son choix de laisser vivre C-18 conduit à leur vie de famille.', 'Goku’s fellow student under Master Roshi, Krillin becomes one of Earth’s most loyal defenders. He helps Gohan on Namek and faces the androids despite their power. His decision to spare Android 18 leads to their family life.', 'Kienzan et Kamehameha', 'Destructo Disc and Kamehameha', 'Krillin vs Nappa@Saiyan|Krillin vs Frieza@Namek|Krillin vs Cell@Cell', 'Époux de C-18 et père de Marron.', 'Android 18’s husband and Marron’s father.'),
    entry('Tenshinhan', 'Tien Shinhan', 'Guerriers Z', 'Ancien élève de l’école de la Grue, Tenshinhan renonce aux projets de son maître et choisit la voie d’un martialiste indépendant. Il meurt en combattant Nappa puis poursuit son entraînement. Son Shin Kikoho retient Cell pour protéger C-18.', 'A former Crane School student, Tien rejects his master’s plans and chooses an independent martial path. He dies fighting Nappa and continues training. His Neo Tri-Beam holds Cell back to protect Android 18.', 'Kikoho et Shin Kikoho', 'Tri-Beam and Neo Tri-Beam', 'Tien vs Nappa@Saiyan|Tien vs Cell@Cell|Tien vs Super Buu@Buu'),
    entry('Yamcha', 'Yamcha', 'Guerriers Z', 'Ancien bandit du désert, Yamcha rejoint Bulma et Goku puis étudie auprès de Tortue Géniale. Les tournois et les entraînements le transforment en défenseur de la Terre. Après sa mort contre un Saibaman, il s’entraîne avec Kaio et reste proche de ses compagnons.', 'A former desert bandit, Yamcha joins Bulma and Goku and studies under Master Roshi. Tournaments and training turn him into an Earth defender. After dying against a Saibaman he trains with King Kai and stays close to his companions.', 'Roga Fufu Ken et Sokidan', 'Wolf Fang Fist and Spirit Ball', 'Yamcha vs Saibaman@Saiyan|Yamcha vs Recoome@OtherWorld|Yamcha vs Android 20@Android', 'Puar est son compagnon de toujours.', 'Puar is his lifelong companion.'),
    entry('Chaozu', 'Chiaotzu', 'Guerriers Z', 'Compagnon de Tenshinhan à l’école de la Grue, Chaozu utilise la télékinésie plutôt que la force brute. Il quitte lui aussi son ancien maître. Son sacrifice contre Nappa ne suffit pas à arrêter le Saiyan, mais il est ensuite ramené à la vie avec ses amis.', 'Tien’s Crane School companion, Chiaotzu uses telekinesis rather than brute force. He also leaves his former master. His sacrifice against Nappa cannot stop the Saiyan, but he is later brought back to life with his friends.', 'Télékinésie et Dodonpa', 'Telekinesis and Dodon Ray', 'Chiaotzu vs Nappa@Saiyan|Chiaotzu vs Guldo@OtherWorld'),
    entry('Tortue Géniale', 'Master Roshi', 'Guerriers Z', 'Maître de l’école de la Tortue, Roshi enseigne à Goku et Krilin que le travail quotidien forge le corps et le caractère. Inventeur du Kamehameha, il reste un guide pour les nouvelles générations. Dans les films de DBZ, il défend encore ses élèves contre de nouvelles menaces.', 'Master of the Turtle School, Roshi teaches Goku and Krillin that daily work shapes body and character. The Kamehameha’s inventor, he remains a guide for new generations. In DBZ films he still defends his students against new threats.', 'Kamehameha et Mafuba', 'Kamehameha and Evil Containment Wave', 'Master Roshi vs Dr Wheelo@Wheelo|Master Roshi vs Frieza soldiers@ResurrectionF', 'Frère de Baba ; maître de Goku, Krilin et Yamcha.', 'Fortuneteller Baba’s brother; teacher of Goku, Krillin and Yamcha.'),
    entry('Trunks du futur', 'Future Trunks', 'Guerriers Z', 'Fils de Vegeta et Bulma dans une chronologie ravagée par les cyborgs, Trunks est entraîné par Gohan. Il voyage dans le passé pour avertir Goku et lui apporter un remède. Après les Cell Games, il revient chez lui assez fort pour vaincre les cyborgs et Cell.', 'Vegeta and Bulma’s son in a timeline devastated by androids, Trunks trains under Gohan. He travels into the past to warn Goku and bring medicine. After the Cell Games he returns home strong enough to defeat the androids and Cell.', 'Super Saiyan et Burning Attack', 'Super Saiyan and Burning Attack', 'Future Trunks vs Frieza@Android|Future Trunks vs Android 18@Android|Future Trunks vs Cell@Cell', 'Fils de Bulma et Vegeta ; élève de Gohan du futur.', 'Son of Bulma and Vegeta; Future Gohan’s student.'),
    entry('Trunks', 'Trunks', 'Guerriers Z', 'Le Trunks de la chronologie principale grandit avec ses parents sur une Terre plus paisible que celle de son homologue futur. Ami de Goten, il atteint jeune le Super Saiyan. Les deux enfants apprennent la fusion auprès de Goku pour combattre Buu.', 'Main-timeline Trunks grows up with his parents on an Earth more peaceful than his future counterpart’s. Goten’s friend, he reaches Super Saiyan young. The children learn fusion from Goku to fight Buu.', 'Super Saiyan et danse de fusion', 'Super Saiyan and Fusion Dance', 'Trunks vs Goten@Tournament|Trunks and Goten vs Android 18@Tournament|Trunks vs Broly@BrolySecond', 'Fils de Bulma et Vegeta ; frère de Bra.', 'Son of Bulma and Vegeta; Bulla’s brother.'),
    entry('Son Goten', 'Goten', 'Guerriers Z', 'Second fils de Goku et Chichi, Goten grandit pendant l’absence de son père. Son entraînement avec Chichi et Gohan révèle un talent précoce pour le Super Saiyan. Avec Trunks, il devient Gotenks grâce à la danse de fusion et affronte la menace de Buu.', 'Goku and Chi-Chi’s second son, Goten grows up during his father’s absence. Training with Chi-Chi and Gohan reveals early Super Saiyan talent. With Trunks he becomes Gotenks through the Fusion Dance to face Buu.', 'Super Saiyan et Kamehameha', 'Super Saiyan and Kamehameha', 'Goten vs Trunks@Tournament|Goten and Trunks vs Android 18@Tournament|Goten vs Broly@BrolySecond', 'Fils de Goku et Chichi ; frère cadet de Gohan.', 'Son of Goku and Chi-Chi; Gohan’s younger brother.'),
    entry('Gotenks', 'Gotenks', 'Fusions', 'Gotenks est la fusion de Goten et Trunks, pas une transformation de l’un d’eux. Ses fanfaronnades cachent une puissance considérable et des techniques inventives. L’entraînement dans la Salle de l’Esprit et du Temps lui permet d’atteindre le Super Saiyan 3 contre Super Buu.', 'Gotenks is Goten and Trunks’ fusion, not a transformation of either child. His boasting hides considerable power and inventive techniques. Training in the Hyperbolic Time Chamber lets him reach Super Saiyan 3 against Super Buu.', 'Super Ghost Kamikaze Attack et Super Saiyan 3', 'Super Ghost Kamikaze Attack and Super Saiyan 3', 'Gotenks vs Majin Buu@Buu|Gotenks vs Super Buu@Buu|Gotenks vs Beerus@BattleGods', 'Fusion de Goten et Trunks.', 'Fusion of Goten and Trunks.'),
    entry('Vegetto', 'Vegito', 'Fusions', 'Goku et Vegeta utilisent les Potaras pour devenir Vegetto après l’absorption de Gohan par Buu. Leur fusion domine l’adversaire, même transformée en bonbon. Vegetto se laisse absorber afin de sauver les compagnons prisonniers dans le corps de Buu.', 'Goku and Vegeta use Potara earrings to become Vegito after Buu absorbs Gohan. Their fusion dominates the enemy even after being turned into candy. Vegito deliberately allows absorption to rescue the friends trapped within Buu.', 'Potaras, Spirit Sword et Final Kamehameha', 'Potara, Spirit Sword and Final Kamehameha', 'Vegito vs Super Buu@Buu', 'Fusion de Goku et Vegeta par les Potaras.', 'Goku and Vegeta’s Potara fusion.'),
    entry('Gogeta', 'Gogeta', 'Fusions', 'Dans le film Fusion Reborn, Goku et Vegeta doivent abandonner leur rivalité pour réaliser la danse de fusion. Après un premier essai raté, Gogeta apparaît face à Janemba. Sa maîtrise du ki met fin à la menace qui bouleverse l’au-delà.', 'In Fusion Reborn, Goku and Vegeta must set aside their rivalry to perform the Fusion Dance. After a failed first attempt, Gogeta appears against Janemba. His ki control ends the threat disrupting the afterlife.', 'Danse de fusion et Stardust Breaker', 'Fusion Dance and Stardust Breaker', 'Gogeta vs Janemba@FusionReborn', 'Fusion de Goku et Vegeta par la danse de fusion.', 'Goku and Vegeta’s Fusion Dance fusion.'),
    entry('Bulma', 'Bulma', 'Capsule Corp', 'Inventrice du radar des Dragon Balls, Bulma lance le voyage qui lui fait rencontrer Goku. Dans DBZ, son intelligence rend possible le voyage sur Namek et la compréhension des cyborgs. Sa famille et Capsule Corp soutiennent les Guerriers Z sans qu’elle soit une combattante régulière.', 'Inventor of the Dragon Radar, Bulma begins the journey that introduces her to Goku. In DBZ her intelligence enables the Namek journey and understanding of the androids. Her family and Capsule Corp support the Z Fighters without making her a regular combatant.', 'Ingénierie et radar des Dragon Balls', 'Engineering and Dragon Radar', '', 'Fille du Dr Brief et de Panchy ; épouse de Vegeta ; mère de Trunks et Bra.', 'Daughter of Dr Brief and Panchy; Vegeta’s wife; mother of Trunks and Bulla.'),
    entry('Chichi', 'Chi-Chi', 'Terre', 'Fille du roi Gyumao, Chichi rencontre Goku enfant et l’épouse après le tournoi. Elle veut donner à Gohan puis Goten une vie sûre et une éducation. Elle connaît aussi les arts martiaux et entraîne Goten pendant l’absence de Goku.', 'Ox-King’s daughter, Chi-Chi meets Goku as a child and marries him after the tournament. She wants Gohan and Goten to have safe lives and an education. She also knows martial arts and trains Goten while Goku is absent.', 'Arts martiaux', 'Martial arts', 'Chi-Chi vs Goku@Tournament|Chi-Chi vs Garlic Jr henchmen@DeadZone', 'Fille de Gyumao ; épouse de Goku ; mère de Gohan et Goten.', 'Ox-King’s daughter; Goku’s wife; mother of Gohan and Goten.'),
    entry('Videl', 'Videl', 'Terre', 'Fille de Mr. Satan, Videl protège sa ville et découvre que Gohan est le Great Saiyaman. Il lui enseigne le contrôle du ki et le vol. Son duel brutal contre Spopovich révèle que le tournoi cache une menace plus grave ; elle construit ensuite sa famille avec Gohan.', 'Mr. Satan’s daughter, Videl protects her city and discovers Gohan is the Great Saiyaman. He teaches her ki control and flight. Her brutal fight with Spopovich reveals a greater threat behind the tournament; she later builds a family with Gohan.', 'Arts martiaux et vol par le ki', 'Martial arts and ki flight', 'Videl vs Spopovich@Tournament|Videl vs Broly@BrolySecond|Videl vs Hirudegarn@DragonFist', 'Fille de Mr. Satan ; épouse de Gohan ; mère de Pan.', 'Mr. Satan’s daughter; Gohan’s wife; Pan’s mother.'),
    entry('Mr. Satan', 'Mr. Satan', 'Terre', 'Champion du monde humain, Mr. Satan reçoit le crédit public de la victoire contre Cell. Malgré ses vantardises, son amitié avec Buu joue un rôle essentiel dans la crise suivante. Il persuade les habitants de la Terre de donner leur énergie au Genki Dama de Goku.', 'The human world champion, Mr. Satan receives public credit for defeating Cell. Despite his boasting, friendship with Buu becomes essential in the next crisis. He persuades Earth’s people to give their energy to Goku’s Spirit Bomb.', 'Arts martiaux et persuasion', 'Martial arts and persuasion', 'Mr Satan vs Cell@Cell|Mr Satan vs Android 18@Tournament|Mr Satan vs gunmen@Buu', 'Père de Videl et grand-père de Pan.', 'Videl’s father and Pan’s grandfather.'),
    entry('Pan', 'Pan', 'Terre', 'Petite-fille de Goku, Pan est présentée à la fin de DBZ comme une enfant déjà passionnée par les arts martiaux. Son entraînement familial lui permet de participer au tournoi. Sa naissance lie les familles de Goku et Mr. Satan.', 'Goku’s granddaughter, Pan appears at DBZ’s ending as a child already enthusiastic about martial arts. Family training lets her enter the tournament. Her birth links Goku’s and Mr. Satan’s families.', 'Arts martiaux et vol', 'Martial arts and flight', 'Pan vs Mo Kekko@Tournament', 'Fille de Gohan et Videl ; petite-fille de Goku et Mr. Satan.', 'Daughter of Gohan and Videl; granddaughter of Goku and Mr. Satan.'),
    entry('Bra', 'Bulla', 'Capsule Corp', 'Fille de Vegeta et Bulma, Bra apparaît à la fin de DBZ au sein d’une famille qui a trouvé une vie paisible sur Terre. Son dossier distingue clairement ce rôle familial de celui d’un guerrier : DBZ ne lui attribue pas de série de combats.', 'Vegeta and Bulma’s daughter, Bulla appears at DBZ’s ending in a family that has found a peaceful Earth life. Her profile distinguishes this family role from that of a warrior: DBZ does not give her a series of battles.', 'Aucune technique de combat documentée dans DBZ', 'No combat technique documented in DBZ', '', 'Fille de Bulma et Vegeta ; sœur cadette de Trunks.', 'Daughter of Bulma and Vegeta; Trunks’ younger sister.'),
    entry('C-16', 'Android 16', 'Cyborgs', 'Construit par le Dr Gero, C-16 est entièrement mécanique et préfère protéger la nature. Il accompagne C-17 et C-18, puis affronte Cell pour les sauver. Sa destruction pendant les Cell Games provoque l’éveil de Gohan en Super Saiyan 2.', 'Built by Dr Gero, Android 16 is fully mechanical and prefers protecting nature. He accompanies Androids 17 and 18 and fights Cell to save them. His destruction at the Cell Games triggers Gohan’s Super Saiyan 2 awakening.', 'Hell’s Flash et puissance mécanique', 'Hell’s Flash and mechanical strength', 'Android 16 vs Cell@Cell', 'Créé par le Dr Gero.', 'Created by Dr Gero.'),
    entry('C-17', 'Android 17', 'Cyborgs', 'Humain transformé par Gero, C-17 tue son créateur après son réveil et cherche sa liberté. Son énergie inépuisable lui permet de tenir tête à Piccolo, mais Cell l’absorbe. Ressuscité après les Cell Games, il choisit une existence indépendante.', 'A human altered by Gero, Android 17 kills his creator after awakening and seeks freedom. Endless energy lets him match Piccolo, but Cell absorbs him. Revived after the Cell Games, he chooses an independent life.', 'Énergie perpétuelle et barrière', 'Endless energy and barrier', 'Android 17 vs Dr Gero@Android|Android 17 vs Piccolo@Android|Android 17 vs Cell@Cell', 'Frère jumeau de C-18 ; son nom humain est Lapis.', 'Android 18’s twin brother; his human name is Lapis.'),
    entry('C-18', 'Android 18', 'Cyborgs', 'Humaine transformée par Gero, C-18 vainc Vegeta avant que Cell ne la poursuive pour atteindre sa forme parfaite. Krilin refuse de la détruire avec la télécommande. Libérée de Cell, elle devient son épouse tout en conservant sa force.', 'A human altered by Gero, Android 18 defeats Vegeta before Cell hunts her to reach perfection. Krillin refuses to destroy her with the remote. Freed from Cell, she becomes his wife while retaining her strength.', 'Énergie perpétuelle et combat rapproché', 'Endless energy and close combat', 'Android 18 vs Vegeta@Android|Android 18 vs Cell@Cell|Android 18 vs Mighty Mask@Tournament', 'Sœur jumelle de C-17 ; épouse de Krilin et mère de Marron.', 'Android 17’s twin sister; Krillin’s wife and Marron’s mother.'),
    entry('C-19', 'Android 19', 'Cyborgs', 'Robot créé par Gero, C-19 absorbe l’énergie par les paumes de ses mains. Il profite de la maladie cardiaque de Goku lors du premier affrontement annoncé par Trunks. Vegeta découvre comment neutraliser son absorption et le détruit.', 'A robot created by Gero, Android 19 absorbs energy through his palms. He exploits Goku’s heart illness in the first confrontation foretold by Trunks. Vegeta discovers how to neutralize his absorption and destroys him.', 'Absorption d’énergie', 'Energy absorption', 'Android 19 vs Goku@Android|Android 19 vs Vegeta@Android', 'Créé par le Dr Gero.', 'Created by Dr Gero.'),
    entry('Dr Gero', 'Dr. Gero', 'Cyborgs', 'Ancien scientifique de l’armée du Ruban Rouge, Gero prépare sa vengeance contre Goku avec des cyborgs. Il transforme aussi son propre corps en C-20. Ses créations C-17 et C-18 échappent à son contrôle, tandis que le projet Cell poursuit son programme.', 'A former Red Ribbon scientist, Gero prepares revenge against Goku through androids. He also turns his body into Android 20. Androids 17 and 18 escape his control while the Cell project continues his programme.', 'Ingénierie des cyborgs et absorption', 'Android engineering and absorption', 'Dr Gero vs Yamcha@Android|Dr Gero vs Piccolo@Android|Dr Gero vs Android 17@Android'),
    entry('C-13', 'Android 13', 'Cyborgs', 'Dans le film Super Android 13, l’ordinateur de Gero active trois nouveaux cyborgs pour tuer Goku. C-13 absorbe les composants de C-14 et C-15 après leur destruction. Sa forme renforcée oblige Goku à rassembler une énergie exceptionnelle.', 'In Super Android 13, Gero’s computer activates three new androids to kill Goku. Android 13 absorbs Androids 14 and 15’s components after their destruction. His enhanced form forces Goku to gather extraordinary energy.', 'S.S. Deadly Bomber et absorption de composants', 'S.S. Deadly Bomber and component absorption', 'Android 13 vs Goku@Android13|Android 13 vs Piccolo@Android13|Android 13 vs Vegeta@Android13'),
    entry('C-14', 'Android 14', 'Cyborgs', 'Activé par l’ordinateur de Gero dans le film Super Android 13, C-14 poursuit la mission de tuer Goku. Sa grande force mécanique s’oppose aux Saiyans. Trunks le détruit, mais ses composants permettent ensuite à C-13 de se renforcer.', 'Activated by Gero’s computer in Super Android 13, Android 14 pursues the mission to kill Goku. His mechanical strength challenges the Saiyans. Trunks destroys him, but his components later strengthen Android 13.', 'Force mécanique et combat rapproché', 'Mechanical strength and close combat', 'Android 14 vs Goku@Android13|Android 14 vs Trunks@Android13'),
    entry('C-15', 'Android 15', 'Cyborgs', 'Petit cyborg activé avec C-13 et C-14, C-15 utilise des attaques de ki et une force disproportionnée à sa taille. Il combat Vegeta dans le film Super Android 13. Après sa destruction, ses pièces rejoignent le corps de C-13.', 'A small android activated with Androids 13 and 14, Android 15 uses ki attacks and strength disproportionate to his size. He fights Vegeta in Super Android 13. After his destruction, his parts join Android 13’s body.', 'Attaques de ki et force mécanique', 'Ki attacks and mechanical strength', 'Android 15 vs Goku@Android13|Android 15 vs Vegeta@Android13'),
    entry('Raditz', 'Raditz', 'Saiyans', 'Frère aîné de Goku, Raditz arrive sur Terre et révèle ses origines saiyannes. Il enlève Gohan pour forcer Goku à le rejoindre. L’alliance de Goku et Piccolo finit par le vaincre, mais son détecteur transmet l’existence des Dragon Balls à ses partenaires.', 'Goku’s older brother, Raditz arrives on Earth and reveals his Saiyan origins. He abducts Gohan to force Goku to join him. Goku and Piccolo’s alliance defeats him, but his scouter transmits the Dragon Balls’ existence to his partners.', 'Double Sunday et attaques de ki', 'Double Sunday and ki attacks', 'Raditz vs Piccolo@Saiyan|Raditz vs Goku and Piccolo@Saiyan|Raditz vs Gohan@Saiyan', 'Fils de Bardock et Gine ; frère de Goku.', 'Son of Bardock and Gine; Goku’s brother.'),
    entry('Nappa', 'Nappa', 'Saiyans', 'Partenaire de Vegeta après la destruction de leur planète, Nappa attaque la Terre à la recherche des Dragon Balls. Sa puissance ravage les rangs des défenseurs. L’arrivée de Goku renverse le combat ; Vegeta élimine ensuite son partenaire blessé.', 'Vegeta’s partner after their planet’s destruction, Nappa attacks Earth seeking the Dragon Balls. His power devastates the defenders. Goku’s arrival turns the battle, and Vegeta then kills his wounded partner.', 'Force saiyanne et explosions de ki', 'Saiyan strength and ki explosions', 'Nappa vs Tien@Saiyan|Nappa vs Piccolo@Saiyan|Nappa vs Goku@Saiyan'),
    entry('Bardock', 'Bardock', 'Saiyans', 'Père de Goku et guerrier de rang inférieur, Bardock mène des missions pour Frieza. Dans le téléfilm DBZ, ses visions et la mort de ses compagnons lui révèlent la trahison du tyran. Il tente d’arrêter la destruction de la planète Vegeta.', 'Goku’s father and a low-class warrior, Bardock carries out missions for Frieza. In the DBZ television special, visions and his companions’ deaths reveal the tyrant’s betrayal. He tries to stop Planet Vegeta’s destruction.', 'Combat saiyan et vague de ki', 'Saiyan combat and ki wave', 'Bardock vs Kanassan warriors@Bardock|Bardock vs Dodoria soldiers@Bardock|Bardock vs Frieza@Bardock', 'Père de Goku et Raditz ; compagnon de Gine.', 'Father of Goku and Raditz; Gine’s partner.'),
    entry('Roi Vegeta', 'King Vegeta', 'Saiyans', 'Souverain des Saiyans et père de Vegeta, le roi sert Frieza tout en cherchant à préserver sa lignée. Dans les souvenirs de DBZ, sa révolte échoue contre le tyran. Le film Broly présente également sa peur de la puissance du nouveau-né Broly.', 'The Saiyans’ ruler and Vegeta’s father, the king serves Frieza while trying to preserve his lineage. In DBZ flashbacks his rebellion fails against the tyrant. The Broly film also portrays his fear of the infant Broly’s power.', 'Puissance saiyanne et attaques de ki', 'Saiyan power and ki attacks', 'King Vegeta vs Frieza@Past', 'Père de Vegeta.', 'Vegeta’s father.'),
    entry('Tora', 'Tora', 'Saiyans', 'Membre de l’équipe de Bardock dans le téléfilm, Tora participe aux conquêtes des Saiyans. Frieza fait tendre une embuscade à ses compagnons sur la planète Meat. Avant de mourir, Tora avertit Bardock de la trahison.', 'A Bardock-team member in the television special, Tora joins Saiyan conquests. Frieza has the team ambushed on Planet Meat. Before dying, Tora warns Bardock of the betrayal.', 'Combat saiyan et ki', 'Saiyan combat and ki', 'Tora vs Kanassan warriors@Bardock|Tora vs Dodoria soldiers@Bardock'),
    entry('Fasha', 'Fasha', 'Saiyans', 'Guerrière de l’équipe de Bardock, Fasha apparaît dans le téléfilm consacré à sa dernière mission. Elle utilise la transformation en grand singe avec ses compagnons. L’embuscade ordonnée par Frieza sur Meat met fin à leur équipe.', 'A warrior on Bardock’s team, Fasha appears in the television special about his final mission. She uses Great Ape transformation alongside her companions. Frieza’s ambush on Meat ends their team.', 'Transformation en grand singe', 'Great Ape transformation', 'Fasha vs Kanassan warriors@Bardock|Fasha vs Dodoria soldiers@Bardock'),
    entry('Borgos', 'Borgos', 'Saiyans', 'Compagnon de Bardock, Borgos est un Saiyan imposant qui prend part aux conquêtes de son équipe. Il est envoyé sur Meat avec Tora, Fasha et Shugesh. Le groupe y est éliminé par les hommes de Frieza.', 'Bardock’s imposing Saiyan companion, Borgos takes part in his team’s conquests. He is sent to Meat with Tora, Fasha and Shugesh. Frieza’s forces eliminate the group there.', 'Force saiyanne et grand singe', 'Saiyan strength and Great Ape form', 'Borgos vs Kanassan warriors@Bardock|Borgos vs Dodoria soldiers@Bardock'),
    entry('Shugesh', 'Shugesh', 'Saiyans', 'Membre de l’escouade de Bardock, Shugesh participe à la conquête de Kanassa. Ses missions montrent la violence des opérations saiyannes au service de Frieza. Il meurt avec ses compagnons dans l’embuscade de Meat.', 'A Bardock-squad member, Shugesh joins the conquest of Kanassa. His missions show the violence of Saiyan operations under Frieza. He dies with his companions in the Meat ambush.', 'Grand singe et combat saiyan', 'Great Ape form and Saiyan combat', 'Shugesh vs Kanassan warriors@Bardock|Shugesh vs Dodoria soldiers@Bardock'),
    entry('Capitaine Ginyu', 'Captain Ginyu', 'Empire de Frieza', 'Chef du commando Ginyu, il associe poses théâtrales et discipline au service de Frieza. Face à la puissance de Goku sur Namek, il échange leurs corps. Sa technique se retourne finalement contre lui lorsqu’il prend le corps d’une grenouille.', 'Leader of the Ginyu Force, he combines theatrical poses with discipline under Frieza. Facing Goku’s power on Namek, he swaps their bodies. His technique ultimately backfires when he takes a frog’s body.', 'Échange des corps', 'Body Change', 'Ginyu vs Goku@Namek|Ginyu vs Vegeta@Namek|Ginyu vs Gohan and Krillin@Namek'),
    entry('Recoome', 'Recoome', 'Empire de Frieza', 'Membre du commando Ginyu, Recoome affiche une endurance exceptionnelle sous ses poses de spectacle. Sur Namek, il écrase Vegeta, Krilin et Gohan. Goku l’arrête avec un seul coup après son arrivée sur la planète.', 'A Ginyu Force member, Recoome hides exceptional endurance beneath showy poses. On Namek he overwhelms Vegeta, Krillin and Gohan. Goku stops him with a single blow after arriving on the planet.', 'Recoome Eraser Gun et endurance', 'Recoome Eraser Gun and endurance', 'Recoome vs Vegeta@Namek|Recoome vs Gohan@Namek|Recoome vs Goku@Namek'),
    entry('Burter', 'Burter', 'Empire de Frieza', 'Membre du commando Ginyu, Burter se présente comme le plus rapide de l’univers. Avec Jeice, il attaque Goku après la défaite de Recoome. Le duel montre que la vitesse qu’il croyait imbattable ne suffit plus.', 'A Ginyu Force member, Burter calls himself the fastest in the universe. With Jeice he attacks Goku after Recoome’s defeat. Their battle shows that the speed he considered unbeatable is no longer enough.', 'Vitesse et attaques combinées', 'Speed and combined attacks', 'Burter and Jeice vs Goku@Namek|Burter vs Tien@OtherWorld'),
    entry('Jeice', 'Jeice', 'Empire de Frieza', 'Soldat rouge du commando Ginyu, Jeice combine ses attaques avec celles de Burter. Après leur échec contre Goku, il ramène son capitaine sur le champ de bataille. Vegeta l’élimine pendant l’affrontement qui suit l’échange des corps.', 'The Ginyu Force’s red soldier, Jeice combines attacks with Burter. After they fail against Goku he brings his captain back to the battlefield. Vegeta kills him during the battle following Body Change.', 'Crusher Ball', 'Crusher Ball', 'Jeice and Burter vs Goku@Namek|Jeice vs Vegeta@Namek|Jeice vs Tien@OtherWorld'),
    entry('Guldo', 'Guldo', 'Empire de Frieza', 'Membre le moins puissant physiquement du commando, Guldo compense par la télékinésie et l’arrêt du temps. Il piège Gohan et Krilin sur Namek. Vegeta intervient avant qu’il ne puisse achever les deux enfants.', 'The Ginyu Force’s physically weakest member, Guldo compensates with telekinesis and stopped time. He traps Gohan and Krillin on Namek. Vegeta intervenes before he can finish them.', 'Arrêt du temps et télékinésie', 'Time Freeze and telekinesis', 'Guldo vs Gohan and Krillin@Namek|Guldo vs Vegeta@Namek|Guldo vs Chiaotzu@OtherWorld'),
    entry('Zarbon', 'Zarbon', 'Empire de Frieza', 'Bras droit de Frieza, Zarbon préfère son apparence élégante mais cache une transformation monstrueuse. Il bat d’abord Vegeta sur Namek puis le récupère pour obtenir des informations. La guérison du Saiyan renverse leur second affrontement.', 'A Frieza officer, Zarbon prefers his elegant appearance but hides a monstrous transformation. He first defeats Vegeta on Namek and retrieves him for information. The Saiyan’s recovery reverses their second confrontation.', 'Transformation monstrueuse', 'Monster transformation', 'Zarbon vs Vegeta round 1@Namek|Zarbon vs Vegeta round 2@Namek'),
    entry('Dodoria', 'Dodoria', 'Empire de Frieza', 'Officier de Frieza, Dodoria terrorise les villages nameks pendant la recherche des Dragon Balls. Gohan et Krilin sauvent Dende de son attaque. Vegeta le poursuit et découvre par lui la vérité sur la destruction de sa planète.', 'A Frieza officer, Dodoria terrorizes Namekian villages while searching for Dragon Balls. Gohan and Krillin save Dende from his attack. Vegeta pursues him and learns through him the truth about his planet’s destruction.', 'Force brute et rayon buccal', 'Brute strength and mouth beam', 'Dodoria vs Namekian warriors@Namek|Dodoria vs Gohan@Namek|Dodoria vs Vegeta@Namek'),
    entry('Cui', 'Cui', 'Empire de Frieza', 'Soldat de Frieza et ancien rival de Vegeta, Cui suppose que leur puissance reste comparable. Il poursuit le Saiyan rebelle sur Namek. L’évolution de Vegeta après les combats sur Terre transforme leur rencontre en défaite immédiate.', 'A Frieza soldier and former Vegeta rival, Cui assumes their power remains comparable. He pursues the rebellious Saiyan on Namek. Vegeta’s growth after fighting on Earth turns their meeting into an immediate defeat.', 'Attaques de ki', 'Ki attacks', 'Cui vs Vegeta@Namek'),
    entry('Roi Cold', 'King Cold', 'Empire de Frieza', 'Père de Frieza, Cold récupère son fils après la destruction de Namek. Ils arrivent sur Terre pour se venger de Goku. Trunks du futur détruit Frieza puis refuse la proposition de Cold, qui tente de le tromper avec son épée.', 'Frieza’s father, Cold retrieves his son after Namek’s destruction. They arrive on Earth to take revenge on Goku. Future Trunks destroys Frieza and rejects Cold’s offer when the king tries to trick him with the sword.', 'Puissance et manipulation', 'Power and manipulation', 'King Cold vs Future Trunks@Android', 'Père de Frieza et de Cooler dans les films.', 'Father of Frieza and, in the films, Cooler.'),
    entry('Fat Buu', 'Majin Buu', 'Majin', 'Libéré par Babidi, Buu ressemble à un enfant joyeux mais détruit sans remords. Il tue Babidi quand celui-ci le dispute, puis se lie d’amitié avec Mr. Satan, qui lui apprend la bonté. Quand des humains blessent son chien, sa colère libère un Buu maléfique séparé de lui.', 'Freed by Babidi, Buu looks like a cheerful child but destroys without remorse. He kills Babidi after being scolded, then befriends Mr. Satan, who teaches him kindness. When humans hurt his dog, his anger releases a separate evil Buu.', 'Régénération, rayon bonbon et Chocolat', 'Regeneration, Candy Beam and chocolate transformation', 'Fat Buu vs Goku@Buu|Fat Buu vs Vegeta@Buu|Fat Buu vs Evil Buu@Buu', 'Créé par le sorcier Bibidi ; son ami Mr. Satan et le chien Bee lui montrent la gentillesse.', 'Created by the wizard Bibidi; his friend Mr. Satan and the dog Bee show him kindness.'),
    entry('Evil Buu', 'Super Buu', 'Majin', 'Sorti de la colère de Fat Buu, Evil Buu est le Buu cruel et rusé qui absorbe ensuite Fat Buu. Il élimine Piccolo, Gotenks et Gohan en absorbant ou en transformant ses adversaires. Après avoir absorbé Gotenks et Piccolo, il devient Super Buu, puis Gohan.', 'Born from Fat Buu’s anger, Evil Buu is the cruel, cunning Buu who later absorbs Fat Buu. He defeats Piccolo, Gotenks and Gohan by absorbing or transforming opponents. After absorbing Gotenks and Piccolo he becomes Super Buu, then absorbs Gohan.', 'Absorption, copie des techniques et Ki Blast', 'Absorption, technique copying and ki blasts', 'Evil Buu vs Gohan@Buu|Evil Buu vs Gotenks@Buu|Evil Buu vs Vegito@Buu', 'Issu de Fat Buu ; il absorbe Gotenks, Piccolo et Gohan.', 'Split from Fat Buu; he absorbs Gotenks, Piccolo and Gohan.'),
    entry('Kid Buu', 'Kid Buu', 'Majin', 'Kid Buu est la forme originelle de Buu, libérée quand Vegeto expulse tous les Buu absorbés. Rapide, imprévisible et sans pitié, il détruit la Terre avant que Goku et Vegeta combattent sur la planète Kaio. Goku utilise la Genkidama avec l’énergie de la Terre entière pour le vaincre.', 'Kid Buu is Buu’s original form, released when Vegito is expelled from absorbed Buu. Fast, unpredictable and merciless, he destroys Earth before Goku and Vegeta fight him at the Supreme Kai’s planet. Goku defeats him with the Spirit Bomb using energy from the whole Earth.', 'Régénération, attaques-bombes et Vanishing Ball', 'Regeneration, blast attacks and Vanishing Ball', 'Kid Buu vs Goku@Buu|Kid Buu vs Vegeta@Buu|Kid Buu vs Gohan@Buu', 'Forme originelle de Buu ; aucun lien de famille.', 'Buu’s original form; no family ties.'),
    entry('Dabra', 'Dabura', 'Majin', 'Roi du monde des démons soumis à Babidi, Dabra garde le vaisseau où l’énergie volée doit réveiller Buu. Sa salive pétrifie Piccolo et Krilin. Après son combat contre Gohan, il comprend trop tard que Buu menace même ses propres alliés.', 'The Demon Realm’s king under Babidi, Dabura guards the ship where stolen energy will awaken Buu. His saliva petrifies Piccolo and Krillin. After fighting Gohan he realizes too late that Buu threatens his own allies.', 'Pétrification et épée démoniaque', 'Petrification and demonic sword', 'Dabura vs Piccolo and Krillin@Buu|Dabura vs Gohan@Buu|Dabura vs Majin Buu@Buu'),
    entry('Babidi', 'Babidi', 'Majin', 'Sorcier cherchant à réveiller Buu, Babidi exploite le mal présent dans les cœurs pour contrôler ses serviteurs. Il manipule Vegeta et collecte l’énergie des combats. Sa certitude de pouvoir commander Buu prend fin lorsque la créature se retourne contre lui.', 'A wizard seeking to awaken Buu, Babidi exploits evil in people’s hearts to control servants. He manipulates Vegeta and gathers battle energy. His belief that he can command Buu ends when the creature turns against him.', 'Magie de contrôle et barrières', 'Control magic and barriers', 'Babidi vs Piccolo@Buu|Babidi vs Majin Buu@Buu', 'Lié au sorcier Bibidi et à son projet de réveil de Buu.', 'Connected to the wizard Bibidi and his plan to awaken Buu.'),
    entry('Spopovich', 'Spopovich', 'Majin', 'Ancien participant humain au tournoi, Spopovich reçoit de Babidi une force et une résistance anormales. Son duel contre Videl montre cette transformation inquiétante. Avec Yamu, il vole l’énergie de Gohan pour alimenter le réveil de Buu.', 'A former human tournament entrant, Spopovich receives unnatural strength and endurance from Babidi. His fight with Videl reveals the disturbing change. With Yamu he steals Gohan’s energy to fuel Buu’s awakening.', 'Puissance et vol accordés par Babidi', 'Power and flight granted by Babidi', 'Spopovich vs Videl@Tournament|Spopovich and Yamu vs Gohan@Tournament'),
    entry('Yamu', 'Yamu', 'Majin', 'Serviteur humain de Babidi, Yamu accompagne Spopovich au tournoi pour voler du ki. Leur attaque contre Gohan conduit les héros jusqu’au vaisseau du sorcier. Une fois leur mission achevée, Babidi se débarrasse d’eux.', 'Babidi’s human servant, Yamu accompanies Spopovich to the tournament to steal ki. Their attack on Gohan leads the heroes to the wizard’s ship. Once their mission is complete, Babidi disposes of them.', 'Collecteur d’énergie et pouvoir majin', 'Energy collector and Majin power', 'Yamu and Spopovich vs Gohan@Tournament'),
    entry('Pui Pui', 'Pui Pui', 'Majin', 'Premier gardien du vaisseau de Babidi, Pui Pui compte sur la gravité de sa planète Zoon pour dominer Vegeta. Il ignore l’entraînement gravitationnel du Saiyan. Vegeta le bat sans même utiliser le Super Saiyan.', 'The first guard in Babidi’s ship, Pui Pui relies on Planet Zoon’s gravity to overwhelm Vegeta. He knows nothing of the Saiyan’s gravity training. Vegeta defeats him without even using Super Saiyan.', 'Combat sous forte gravité', 'High-gravity combat', 'Pui Pui vs Vegeta@Buu'),
    entry('Yakon', 'Yakon', 'Majin', 'Monstre gardien du deuxième niveau de Babidi, Yakon absorbe la lumière plutôt que le ki ordinaire. Goku utilise le Super Saiyan pour l’attirer. Une brusque augmentation d’énergie le fait absorber davantage qu’il ne peut contenir.', 'Babidi’s second-floor monster guard, Yakon consumes light rather than ordinary ki. Goku uses Super Saiyan to attract him. A sudden energy increase makes him swallow more than he can contain.', 'Absorption de lumière', 'Light absorption', 'Yakon vs Goku@Buu'),
    entry('Dende', 'Dende', 'Nameks', 'Enfant namek sauvé par Gohan et Krilin, Dende devient un allié essentiel contre Frieza grâce à ses soins. Il succède ensuite à Kami comme gardien de la Terre. Son pouvoir restaure les Dragon Balls et permet aux héros de réparer les conséquences des guerres.', 'A Namekian child saved by Gohan and Krillin, Dende becomes essential against Frieza through healing. He later succeeds Kami as Earth’s guardian. His power restores the Dragon Balls and helps the heroes repair the consequences of war.', 'Guérison et création des Dragon Balls', 'Healing and Dragon Ball creation', '', 'Enfant du Grand Doyen namek.', 'A child of Namek’s Grand Elder.'),
    entry('Nail', 'Nail', 'Nameks', 'Guerrier protecteur du Grand Doyen, Nail affronte Frieza pour gagner le temps nécessaire à l’invocation de Porunga. Gravement blessé, il rencontre Piccolo et lui propose une assimilation. Son sacrifice transmet sa force au nouveau combattant.', 'The Grand Elder’s warrior protector, Nail fights Frieza to buy time to summon Porunga. Gravely wounded, he meets Piccolo and offers assimilation. His sacrifice passes his strength to the new fighter.', 'Régénération et assimilation namek', 'Namekian regeneration and assimilation', 'Nail vs Frieza@Namek'),
    entry('Kami', 'Kami', 'Nameks', 'Gardien namek de la Terre, Kami a séparé son mal pour obtenir cette fonction, donnant naissance à Piccolo Daimao. Il crée les Dragon Balls terrestres et guide les héros. La menace de Cell le convainc de se réunir avec Piccolo.', 'Earth’s Namekian guardian, Kami separated his evil to gain the role, creating King Piccolo. He makes Earth’s Dragon Balls and guides the heroes. Cell’s threat convinces him to reunite with Piccolo.', 'Création des Dragon Balls et magie', 'Dragon Ball creation and magic', 'Kami vs Garlic Jr@DeadZone', 'Autre moitié originelle de Piccolo.', 'Piccolo’s original other half.'),
    entry('Mr. Popo', 'Mr. Popo', 'Terre', 'Serviteur du sanctuaire et assistant des gardiens de la Terre, Mr. Popo aide Kami puis Dende. Il prépare les défenseurs contre les Saiyans et guide Bulma vers le vaisseau namek. La Salle de l’Esprit et du Temps fait partie des ressources qu’il leur présente.', 'The Lookout’s attendant and assistant to Earth’s guardians, Mr. Popo helps Kami and then Dende. He trains the defenders against the Saiyans and guides Bulma to the Namekian spaceship. He introduces resources such as the Hyperbolic Time Chamber.', 'Arts martiaux et maîtrise du sanctuaire', 'Martial arts and Lookout knowledge', 'Mr Popo vs Goten and Trunks@Buu'),
    entry('Kaio du Nord', 'King Kai', 'Divinités', 'Kaio entraîne Goku dans l’au-delà avant l’arrivée des Saiyans. La gravité de sa planète et ses exercices précèdent l’enseignement du Kaioken et du Genki Dama. Il sert aussi de relais télépathique aux héros, même après la destruction de sa planète par Cell.', 'King Kai trains Goku in the afterlife before the Saiyans arrive. His planet’s gravity and exercises precede the Kaio-ken and Spirit Bomb lessons. He also relays telepathic messages, even after Cell destroys his planet.', 'Télépathie, Kaioken et Genki Dama', 'Telepathy, Kaio-ken and Spirit Bomb', '', 'Bubbles et Gregory vivent avec lui.', 'Bubbles and Gregory live with him.'),
    entry('Kibito', 'Kibito', 'Divinités', 'Assistant du Kaioshin de l’Est, Kibito aide à détecter le projet de Babidi au tournoi. Dabra le tue avant son retour grâce aux Dragon Balls. Sa téléportation et ses soins permettent de transporter et préparer Gohan sur le monde des Kaioshins.', 'The East Supreme Kai’s attendant, Kibito helps detect Babidi’s plan at the tournament. Dabura kills him before the Dragon Balls revive him. His teleportation and healing help transport and prepare Gohan on the Supreme Kais’ world.', 'Téléportation et guérison', 'Teleportation and healing', 'Kibito vs Dabura@Buu'),
    entry('Shin', 'Shin', 'Divinités', 'Kaioshin de l’Est et survivant de l’attaque originelle de Buu, Shin suit Babidi jusqu’à la Terre. Il recrute les Saiyans mais sous-estime leur puissance. Après le retour de Buu, il conduit Gohan sur son monde pour préparer une nouvelle défense.', 'The East Supreme Kai and a survivor of Buu’s original attack, Shin follows Babidi to Earth. He recruits the Saiyans but underestimates their power. After Buu returns he takes Gohan to his world to prepare a new defence.', 'Télékinésie et pouvoirs kaioshins', 'Telekinesis and Supreme Kai powers', 'Shin vs Majin Buu@Buu'),
    entry('Vieux Kaioshin', 'Old Kai', 'Divinités', 'Ancien Kaioshin enfermé dans l’épée Z, il est libéré lorsque Gohan brise la lame. Son rituel révèle le potentiel du jeune Saiyan. Il transmet aussi les Potaras et donne sa propre vie à Goku pour lui permettre de retourner combattre Buu.', 'An ancient Supreme Kai sealed in the Z Sword, he is freed when Gohan breaks the blade. His ritual reveals the young Saiyan’s potential. He also gives the Potara earrings and his own life to Goku so he can return against Buu.', 'Rituel de libération du potentiel', 'Potential-unlocking ritual', ''),
    entry('Grand Kaioshin', 'Grand Supreme Kai', 'Divinités', 'Chef bienveillant des Kaioshins à l’époque de l’attaque de Buu, le Grand Kaioshin tente de défendre ses compagnons. Buu l’absorbe. Son influence apaise la créature et explique en partie la bonté qui subsiste dans le Buu rond de DBZ.', 'The Supreme Kais’ kind leader during Buu’s original attack, the Grand Supreme Kai tries to protect his companions. Buu absorbs him. His influence softens the creature and partly explains the kindness remaining in DBZ’s round Buu.', 'Pouvoirs divins', 'Divine powers', 'Grand Supreme Kai vs Majin Buu@Past'),
    entry('Grand Kaio', 'Grand Kai', 'Divinités', 'Dans les épisodes de l’au-delà de DBZ, le Grand Kaio supervise les quatre Kaios et leur tournoi. Les guerriers espèrent recevoir son entraînement. Son rôle est celui d’un arbitre et d’un maître supérieur, pas d’un adversaire régulier.', 'In DBZ’s afterlife episodes, the Grand Kai oversees the four Kais and their tournament. Warriors hope to receive his training. His role is that of a referee and senior teacher, not a regular opponent.', 'Supervision et entraînement des guerriers', 'Warrior supervision and training', ''),
    entry('Kaio du Sud', 'South Kai', 'Divinités', 'Kaio responsable du secteur sud dans les épisodes de l’au-delà, il rivalise avec les autres Kaios pour mettre en valeur ses élèves. Son orgueil fait partie du tournoi de l’autre monde. DBZ ne lui attribue pas trois combats personnels.', 'The southern sector’s Kai in the afterlife episodes, he competes with the other Kais to showcase his pupils. His pride shapes the Other World Tournament. DBZ does not give him three personal battles.', 'Enseignement et pouvoirs de Kaio', 'Teaching and Kai powers', ''),
    entry('Paikuhan', 'Pikkon', 'Au-delà', 'Guerrier de l’au-delà entraîné sous l’autorité du Kaio de l’Ouest, Paikuhan maîtrise un ki associé au feu et au vent. Il neutralise des ennemis en enfer puis rivalise avec Goku au tournoi. Il aide aussi les Saiyans dans le film Fusion Reborn.', 'An afterlife warrior under the West Kai, Pikkon masters fire- and wind-linked ki. He subdues enemies in Hell and rivals Goku at the tournament. He also helps the Saiyans in Fusion Reborn.', 'Thunder Flash et Hyper Tornado', 'Thunder Flash and Hyper Tornado', 'Pikkon vs Cell@OtherWorld|Pikkon vs Goku@OtherWorld|Pikkon vs Janemba@FusionReborn'),
    entry('Kaio de l’Ouest', 'West Kai', 'Divinités', 'Responsable du secteur ouest, ce Kaio présente Paikuhan au tournoi de l’autre monde. Il entretient une rivalité avec le Kaio du Nord et espère la victoire de son élève. Son rôle donne un contexte à l’apprentissage des guerriers morts.', 'The western sector’s Kai presents Pikkon at the Other World Tournament. He maintains a rivalry with the North Kai and hopes his pupil wins. His role provides context for the training of deceased warriors.', 'Enseignement des guerriers de l’au-delà', 'Teaching afterlife warriors', ''),
    entry('Cooler', 'Cooler', 'Films DBZ', 'Frère de Frieza dans les films DBZ, Cooler vient sur Terre pour venger sa famille. Sa transformation supplémentaire menace Goku. Dans sa seconde apparition, le Big Gete Star transforme ses restes en une armée de corps métalliques.', 'Frieza’s brother in the DBZ films, Cooler comes to Earth to avenge his family. His additional transformation threatens Goku. In his second appearance, the Big Gete Star turns his remains into an army of metal bodies.', 'Transformation et corps métalliques', 'Transformation and metal bodies', 'Cooler vs Goku@Cooler|Metal Cooler vs Goku@MetalCooler|Metal Cooler vs Vegeta@MetalCooler', 'Fils de Cold et frère de Frieza dans la continuité des films.', 'Cold’s son and Frieza’s brother in the films’ continuity.'),
    entry('Salza', 'Salza', 'Films DBZ', 'Chef de l’escadron de Cooler, Salza dirige la recherche de Goku sur Terre. Il affronte les défenseurs avant l’arrivée de son maître. Son rayon en lame et ses tactiques ne lui permettent pas de survivre à l’intervention de Piccolo.', 'Cooler’s squadron leader, Salza directs the search for Goku on Earth. He fights the defenders before his master arrives. His blade beam and tactics cannot save him from Piccolo’s intervention.', 'Lame de ki', 'Ki blade', 'Salza vs Gohan@Cooler|Salza vs Piccolo@Cooler|Salza vs Goku@Cooler'),
    entry('Dore', 'Dore', 'Films DBZ', 'Soldat massif de l’escadron de Cooler, Dore traque Goku et ses amis avec Salza et Neiz. Sa force physique domine ses attaques. Piccolo rejoint la bataille et élimine ce combattant avant le duel contre Cooler.', 'The imposing member of Cooler’s squadron, Dore hunts Goku and his friends with Salza and Neiz. Physical strength dominates his attacks. Piccolo joins the battle and eliminates him before the Cooler duel.', 'Force physique et saisies', 'Physical strength and grappling', 'Dore vs Gohan@Cooler|Dore vs Piccolo@Cooler'),
    entry('Neiz', 'Neiz', 'Films DBZ', 'Membre de l’escadron de Cooler, Neiz accompagne ses partenaires dans la poursuite des héros. Son attaque électrique tente de paralyser Piccolo. Le Namek lui renvoie sa propre énergie et met fin à sa participation à la bataille.', 'A Cooler-squadron member, Neiz joins his partners in pursuing the heroes. His electric attack tries to paralyze Piccolo. The Namekian sends his own energy back and ends his part in the battle.', 'Décharge électrique', 'Electric discharge', 'Neiz vs Gohan@Cooler|Neiz vs Piccolo@Cooler'),
    entry('Turles', 'Turles', 'Films DBZ', 'Saiyan ressemblant à Goku, Turles dirige des pirates qui plantent l’Arbre de puissance sur Terre. Les fruits de l’arbre drainent la planète pour augmenter sa force. Il tente de recruter Gohan avant de combattre Goku dans le film du même nom.', 'A Saiyan resembling Goku, Turles leads pirates who plant the Tree of Might on Earth. The tree’s fruit drains the planet to increase his strength. He tries to recruit Gohan before fighting Goku in the film.', 'Fruits de l’Arbre de puissance et ki', 'Tree of Might fruit and ki', 'Turles vs Piccolo@Tree|Turles vs Gohan@Tree|Turles vs Goku@Tree'),
    entry('Amond', 'Amond', 'Films DBZ', 'Membre des pirates de Turles, Amond participe à l’installation de l’Arbre de puissance. Ses attaques massives défendent l’arbre contre les Guerriers Z. Il affronte Krilin avant l’intervention décisive de Goku.', 'A Turles-pirate member, Amond helps establish the Tree of Might. His heavy attacks defend the tree against the Z Fighters. He faces Krillin before Goku’s decisive intervention.', 'Tornade et explosions de ki', 'Tornado and ki blasts', 'Amond vs Krillin@Tree|Amond vs Goku@Tree'),
    entry('Daiz', 'Daiz', 'Films DBZ', 'Pirate de Turles, Daiz combat les défenseurs de la Terre pendant l’invasion de l’Arbre de puissance. Il utilise des projectiles de ki et le combat rapproché. Son affrontement avec Goku conclut sa participation à l’attaque.', 'A Turles pirate, Daiz fights Earth’s defenders during the Tree of Might invasion. He uses ki projectiles and close combat. His confrontation with Goku ends his participation in the attack.', 'Attaques de ki et combat rapproché', 'Ki attacks and close combat', 'Daiz vs Goku@Tree'),
    entry('Cacao', 'Cacao', 'Films DBZ', 'Combattant cyborg des pirates de Turles, Cacao emploie son armement mécanique pour défendre l’Arbre de puissance. Il attaque les Guerriers Z pendant qu’ils cherchent à sauver la Terre. Goku doit neutraliser ces gardiens avant d’affronter Turles.', 'The Turles pirates’ cyborg fighter, Cacao uses mechanical weapons to defend the Tree of Might. He attacks the Z Fighters as they try to save Earth. Goku must neutralize these guards before confronting Turles.', 'Armement cyborg', 'Cyborg weapons', 'Cacao vs Goku@Tree'),
    entry('Rasin', 'Rasin', 'Films DBZ', 'Frère jumeau de Lakasei et membre des pirates de Turles, Rasin attaque en combinaison avec son frère. Ils participent à la défense de l’Arbre de puissance. Leur coordination oppose deux combattants aux héros qui tentent de détruire l’arbre.', 'Lakasei’s twin brother and a Turles-pirate member, Rasin attacks in combination with his brother. They help defend the Tree of Might. Their coordination pits two fighters against the heroes trying to destroy the tree.', 'Attaques jumelles de ki', 'Twin ki attacks', 'Rasin and Lakasei vs Tien and Chiaotzu@Tree|Rasin vs Goku@Tree', 'Frère jumeau de Lakasei.', 'Lakasei’s twin brother.'),
    entry('Lakasei', 'Lakasei', 'Films DBZ', 'Jumeau de Rasin, Lakasei accompagne l’expédition de Turles sur Terre. Son style repose sur les attaques coordonnées de leur duo. Il défend l’Arbre de puissance jusqu’à l’arrivée de Goku.', 'Rasin’s twin, Lakasei accompanies Turles’ expedition to Earth. His style relies on their coordinated attacks. He defends the Tree of Might until Goku arrives.', 'Attaques jumelles de ki', 'Twin ki attacks', 'Lakasei and Rasin vs Tien and Chiaotzu@Tree|Lakasei vs Goku@Tree', 'Frère jumeau de Rasin.', 'Rasin’s twin brother.'),
    entry('Slug', 'Lord Slug', 'Films DBZ', 'Super Namek maléfique, Slug arrive sur Terre avec une armée et cherche les Dragon Balls pour retrouver sa jeunesse. Sa transformation géante menace les défenseurs. Piccolo exploite la sensibilité de l’ouïe namek pour donner une chance à Goku.', 'An evil Super Namekian, Slug arrives on Earth with an army and seeks the Dragon Balls to regain youth. His giant form threatens the defenders. Piccolo exploits Namekian hearing sensitivity to give Goku a chance.', 'Gigantisme et régénération namek', 'Namekian gigantism and regeneration', 'Lord Slug vs Goku@Slug|Lord Slug vs Piccolo@Slug|Lord Slug vs Gohan@Slug'),
    entry('Angila', 'Angila', 'Films DBZ', 'Soldat de Slug, Angila participe à l’occupation de la Terre. Ses bras extensibles lui permettent d’attaquer à distance. Avec Medamatcha, il menace Gohan et Piccolo avant d’être arrêté par Goku.', 'A Slug soldier, Angila joins Earth’s occupation. His extending arms let him attack at a distance. With Medamatcha he threatens Gohan and Piccolo before Goku stops him.', 'Bras extensibles et ki', 'Extending arms and ki', 'Angila vs Gohan@Slug|Angila vs Piccolo@Slug|Angila vs Goku@Slug'),
    entry('Dorodabo', 'Dorodabo', 'Films DBZ', 'Guerrier ailé de Slug, Dorodabo prend part à l’attaque de la Terre. Son combat contre Piccolo oppose sa force physique à l’expérience du Namek. Il disparaît avant l’affrontement final contre son maître.', 'A winged Slug warrior, Dorodabo joins the attack on Earth. Fighting Piccolo pits his physical strength against the Namekian’s experience. He falls before the final confrontation with his master.', 'Vol et force physique', 'Flight and physical strength', 'Dorodabo vs Piccolo@Slug'),
    entry('Medamatcha', 'Medamatcha', 'Films DBZ', 'Serviteur de Slug, Medamatcha produit de petites copies qui absorbent l’énergie de leur cible. Ces créatures affaiblissent Gohan pendant l’invasion. Piccolo puis Goku interviennent pour empêcher son groupe de les achever.', 'A Slug servant, Medamatcha creates small copies that absorb their target’s energy. These creatures weaken Gohan during the invasion. Piccolo and then Goku intervene to stop his group finishing them.', 'Copies absorbant l’énergie', 'Energy-draining copies', 'Medamatcha vs Gohan@Slug|Medamatcha vs Piccolo@Slug|Medamatcha vs Goku@Slug'),
    entry('Tapion', 'Tapion', 'Films DBZ', 'Héros de Conuts dans Wrath of the Dragon, Tapion accepte d’emprisonner une partie d’Hirudegarn dans son corps. Libéré sur Terre par Hoi, il lutte pour contenir le monstre. Son amitié avec Trunks éclaire le poids de son sacrifice.', 'A Conuts hero in Wrath of the Dragon, Tapion accepts imprisoning part of Hirudegarn within his body. Freed on Earth by Hoi, he struggles to contain the monster. His friendship with Trunks reveals the burden of his sacrifice.', 'Ocarina de confinement et épée', 'Containment ocarina and sword', 'Tapion vs Hirudegarn@DragonFist', 'Frère aîné de Minotia.', 'Minotia’s older brother.'),
    entry('Garlic Jr.', 'Garlic Jr.', 'Films DBZ', 'Fils d’un prétendant déchu au rôle de gardien, Garlic Jr. enlève Gohan et obtient l’immortalité. Il ouvre la Dead Zone mais Gohan le repousse dedans. L’anime DBZ lui donne ensuite une seconde invasion pendant l’absence de Goku.', 'The son of a rejected guardian candidate, Garlic Jr. abducts Gohan and obtains immortality. He opens the Dead Zone but Gohan pushes him into it. The DBZ anime later gives him a second invasion while Goku is absent.', 'Immortalité et Dead Zone', 'Immortality and Dead Zone', 'Garlic Jr vs Kami@DeadZone|Garlic Jr vs Goku and Piccolo@DeadZone|Garlic Jr vs Gohan@Garlic', 'Fils de Garlic.', 'Garlic’s son.'),
    entry('Ginger', 'Ginger', 'Films DBZ', 'L’un des trois serviteurs de Garlic Jr. dans Dead Zone, Ginger aide à enlever Gohan. Ses armes et sa transformation défendent le palais de son maître. Goku le combat pendant la tentative de sauvetage.', 'One of Garlic Jr.’s three Dead Zone servants, Ginger helps abduct Gohan. His weapons and transformation defend his master’s palace. Goku fights him during the rescue attempt.', 'Transformation et armes', 'Transformation and weapons', 'Ginger vs Goku@DeadZone'),
    entry('Nicky', 'Nicky', 'Films DBZ', 'Complice de Garlic Jr., Nicky participe à l’enlèvement de Gohan et au vol de la Dragon Ball. Il défend ensuite le château de son maître contre Goku. Son rôle appartient au film Dead Zone, distinct des autres serviteurs de l’arc anime.', 'A Garlic Jr. accomplice, Nicky helps abduct Gohan and steal the Dragon Ball. He then defends his master’s castle against Goku. His role belongs to Dead Zone, distinct from the anime arc’s other servants.', 'Lames et transformation', 'Blades and transformation', 'Nicky vs Chi-Chi@DeadZone|Nicky vs Goku@DeadZone'),
    entry('Sansho', 'Sansho', 'Films DBZ', 'Serviteur massif de Garlic Jr., Sansho aide ses compagnons à attaquer la famille de Goku. Lorsque Piccolo rejoint le sauvetage, Sansho tente de l’arrêter. Le Namek le vainc avant de retrouver les autres héros.', 'Garlic Jr.’s imposing servant, Sansho helps his companions attack Goku’s family. When Piccolo joins the rescue, Sansho tries to stop him. The Namekian defeats him before rejoining the other heroes.', 'Force brute et transformation', 'Brute strength and transformation', 'Sansho vs Piccolo@DeadZone'),
    entry('Dr Wheelo', 'Dr. Wheelo', 'Films DBZ', 'Scientifique dont le cerveau est conservé dans une machine, Wheelo cherche le corps du plus fort combattant. Kochin le libère de la glace et attire les héros dans son laboratoire. Son projet de transfert de cerveau conduit au combat de The World’s Strongest.', 'A scientist whose brain survives inside a machine, Wheelo seeks the strongest fighter’s body. Kochin frees him from the ice and draws the heroes to the laboratory. His brain-transfer plan drives The World’s Strongest’s battle.', 'Corps robotique et rayons', 'Robotic body and beams', 'Dr Wheelo vs Goku@Wheelo|Dr Wheelo vs Piccolo@Wheelo|Dr Wheelo vs Gohan@Wheelo'),
    entry('Dr Kochin', 'Dr. Kochin', 'Films DBZ', 'Assistant du Dr Wheelo, Kochin utilise les Dragon Balls pour libérer le laboratoire gelé. Il crée des bio-guerriers et fait enlever Bulma et Tortue Géniale. Ses expériences servent le projet de donner un nouveau corps à Wheelo.', 'Dr Wheelo’s assistant, Kochin uses the Dragon Balls to free the frozen laboratory. He creates bio-warriors and abducts Bulma and Master Roshi. His experiments serve the plan to give Wheelo a new body.', 'Bio-ingénierie et armes mécaniques', 'Bioengineering and mechanical weapons', 'Dr Kochin vs Krillin@Wheelo'),
    entry('Kishime', 'Kishime', 'Films DBZ', 'Bio-guerrier créé par Kochin, Kishime emploie des attaques électriques dans le laboratoire de Wheelo. Avec les autres gardiens, il teste les combattants capturés et bloque l’arrivée de Goku. Son rôle est propre au film The World’s Strongest.', 'A bio-warrior created by Kochin, Kishime uses electric attacks inside Wheelo’s laboratory. With the other guards he tests captured fighters and blocks Goku’s arrival. His role belongs to The World’s Strongest.', 'Attaques électriques', 'Electric attacks', 'Kishime vs Master Roshi@Wheelo|Kishime vs Goku@Wheelo'),
    entry('Misokatsun', 'Misokatsun', 'Films DBZ', 'Bio-guerrier de Kochin, Misokatsun possède un corps souple qui absorbe les impacts. Il garde le laboratoire où Wheelo cherche un hôte. Goku doit adapter sa force pour traverser cette défense inhabituelle.', 'Kochin’s bio-warrior Misokatsun has a flexible body that absorbs impacts. He guards the laboratory where Wheelo seeks a host. Goku must adjust his power to break through this unusual defence.', 'Corps élastique', 'Elastic body', 'Misokatsun vs Master Roshi@Wheelo|Misokatsun vs Goku@Wheelo'),
    entry('Ebifurya', 'Ebifurya', 'Films DBZ', 'Création de Kochin dans The World’s Strongest, Ebifurya utilise le froid pour immobiliser ses adversaires. Il fait partie des trois bio-guerriers du laboratoire. Son attaque de glace retient Goku jusqu’à ce que celui-ci libère davantage de ki.', 'Kochin’s creation in The World’s Strongest, Ebifurya uses cold to immobilize opponents. He is one of the laboratory’s three bio-warriors. His freezing attack holds Goku until he releases more ki.', 'Souffle glacé', 'Freezing breath', 'Ebifurya vs Master Roshi@Wheelo|Ebifurya vs Goku@Wheelo'),
    entry('Broly', 'Broly', 'Films DBZ', 'Le Broly des films DBZ est un Saiyan dont la puissance effraie le roi Vegeta dès l’enfance. Paragus tente de le contrôler, mais sa rage détruit cette maîtrise. Goku et ses amis doivent unir leurs forces ; ses retours menacent ensuite Gohan, Goten et Trunks.', 'DBZ’s film Broly is a Saiyan whose power frightens King Vegeta from infancy. Paragus tries to control him, but rage breaks that control. Goku and his friends must unite; his later returns threaten Gohan, Goten and Trunks.', 'Super Saiyan légendaire et ki massif', 'Legendary Super Saiyan and massive ki', 'Broly vs Goku@Broly|Broly vs Vegeta@Broly|Broly vs Gohan@BrolySecond', 'Fils de Paragus ; cette fiche traite le Broly des films DBZ.', 'Paragus’ son; this profile covers DBZ’s film Broly.'),
    entry('Paragus', 'Paragus', 'Films DBZ', 'Père de Broly dans les films DBZ, Paragus survit avec son fils à la condamnation du roi Vegeta. Il prépare sa revanche en attirant Vegeta sur une fausse nouvelle planète saiyanne. Son dispositif de contrôle échoue lorsque Broly se libère.', 'Broly’s father in the DBZ films, Paragus survives King Vegeta’s death sentence with his son. He plots revenge by luring Vegeta to a false new Saiyan planet. His control device fails when Broly breaks free.', 'Contrôle technologique de Broly', 'Technological control of Broly', 'Paragus vs Broly@Broly', 'Père de Broly.', 'Broly’s father.'),
    entry('Bojack', 'Bojack', 'Films DBZ', 'Pirate galactique emprisonné par les Kaios, Bojack est libéré lorsque Cell détruit la planète du Kaio du Nord. Il infiltre un tournoi terrestre avec sa bande. Gohan doit reprendre confiance et employer le Super Saiyan 2 pour le vaincre.', 'A galactic pirate imprisoned by the Kais, Bojack is freed when Cell destroys King Kai’s planet. He infiltrates an Earth tournament with his gang. Gohan must regain confidence and use Super Saiyan 2 to defeat him.', 'Transformation et Galactic Buster', 'Transformation and Galactic Buster', 'Bojack vs Vegeta@Bojack|Bojack vs Piccolo@Bojack|Bojack vs Gohan@Bojack'),
    entry('Bujin', 'Bujin', 'Films DBZ', 'Membre de la bande de Bojack, Bujin emploie des fils d’énergie pour restreindre les mouvements adverses. Il participe au piège du tournoi. Gohan brise finalement les attaques coordonnées de la bande après avoir retrouvé sa puissance.', 'A Bojack-gang member, Bujin uses energy threads to restrict opponents’ movement. He joins the tournament trap. Gohan finally breaks the gang’s coordinated attacks after recovering his power.', 'Fils d’énergie et télékinésie', 'Energy threads and telekinesis', 'Bujin vs Gohan@Bojack'),
    entry('Bido', 'Bido', 'Films DBZ', 'Combattant massif du groupe de Bojack, Bido participe à l’invasion du tournoi terrestre. Sa force complète les techniques de restriction de ses partenaires. Gohan doit surmonter cette attaque collective avant de défier Bojack.', 'The imposing Bojack-gang fighter, Bido joins the invasion of Earth’s tournament. His strength complements his partners’ restraint techniques. Gohan must overcome their collective attack before challenging Bojack.', 'Force physique et ki', 'Physical strength and ki', 'Bido vs Gohan@Bojack'),
    entry('Zangya', 'Zangya', 'Films DBZ', 'Guerrière de la bande de Bojack, Zangya combat dans le tournoi organisé sur Terre. Elle élimine Krilin puis aide ses partenaires à encercler Gohan. Bojack la sacrifie lui-même lorsque le jeune Saiyan renverse la bataille.', 'A Bojack-gang warrior, Zangya fights in Earth’s tournament. She defeats Krillin and helps her partners surround Gohan. Bojack himself sacrifices her when the young Saiyan turns the battle.', 'Ki et attaques combinées', 'Ki and combined attacks', 'Zangya vs Krillin@Bojack|Zangya vs Gohan@Bojack'),
    entry('Gokua', 'Gokua', 'Films DBZ', 'Épéiste de la bande de Bojack, Gokua rencontre Trunks du futur pendant le tournoi. Il utilise une transformation pour renforcer sa force. Le Super Saiyan de Trunks met fin à ce premier duel contre les envahisseurs.', 'The Bojack gang’s swordsman, Gokua meets Future Trunks during the tournament. He transforms to strengthen his power. Trunks’ Super Saiyan ends this opening duel against the invaders.', 'Épée et transformation', 'Sword and transformation', 'Gokua vs Future Trunks@Bojack'),
    entry('Janemba', 'Janemba', 'Films DBZ', 'Né d’un accident dans la machine de purification des âmes, Janemba déforme l’au-delà et libère les morts. Sa forme enfantine puis son corps de guerrier déjouent les attaques de Goku et Vegeta. Leur fusion en Gogeta permet de purifier cette menace.', 'Born from an accident in the soul-cleansing machine, Janemba distorts the afterlife and releases the dead. His childish and warrior forms evade Goku and Vegeta’s attacks. Their fusion into Gogeta purifies the threat.', 'Distorsion de l’espace et épée dimensionnelle', 'Spatial distortion and dimensional sword', 'Janemba vs Goku@FusionReborn|Janemba vs Vegeta@FusionReborn|Janemba vs Gogeta@FusionReborn')
  ];
  return { onepiece, dbz };
})();
